script:
frappe.ui.form.on('Quotation', {
    refresh: function(frm) {
        if (frm.is_new() || frm.doc.docstatus === 2) {
            return;
        }

        var get_customer = function() {
            if (frm.doc.quotation_to === 'Customer') {
                return frm.doc.party_name || frm.doc.customer;
            }
            return frm.doc.customer || null;
        };

        var strip_html = function(v) {
            if (!v) {
                return v;
            }
            return String(v).replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]*>/g, '').trim();
        };

        frappe.db.count('Solar Loan', { filters: { quotation: frm.doc.name } }).then(function(n) {
            if (n) {
                return;
            }
            frm.add_custom_button('Loan', function() {
                frappe.model.with_doctype('Solar Loan', function() {
                    var d = frappe.model.get_new_doc('Solar Loan');
                    d.quotation = frm.doc.name;
                    d.customer = get_customer();
                    d.customer_name = frm.doc.customer_name;
                    d.company = frm.doc.company;
                    d.contact_no = frm.doc.contact_mobile || frm.doc.contact_phone;
                    d.email = frm.doc.contact_email;
                    d.address = strip_html(frm.doc.address_display);
                    d.loan_amount = frm.doc.grand_total;
                    d.total_quantity = frm.doc.total_qty;
                    d.base_total = frm.doc.base_total;
                    d.total = frm.doc.total;
                    d.base_net_total = frm.doc.base_net_total;
                    d.net_total = frm.doc.net_total;
                    frappe.set_route('Form', 'Solar Loan', d.name);
                });
            }, 'Create');
        });

        frappe.db.count('Site Visit', { filters: { quotation: frm.doc.name } }).then(function(n) {
            if (n) {
                return;
            }
            frm.add_custom_button('Site Visit', function() {
                frappe.model.with_doctype('Site Visit', function() {
                    var d = frappe.model.get_new_doc('Site Visit');
                    d.quotation = frm.doc.name;
                    d.customer = get_customer();
                    d.company = frm.doc.company;
                    d.contact_person = frm.doc.contact_display;
                    d.phone = frm.doc.contact_mobile || frm.doc.contact_phone;
                    d.location_site_address = strip_html(frm.doc.address_display);
                    frappe.set_route('Form', 'Site Visit', d.name);
                });
            }, 'Create');
        });

        // Query the parent Sales Order: child tables like Sales Order Item have no
        // permissions of their own, so querying them directly fails for non-admin users.
        frappe.db.get_list('Sales Order', {
            filters: [['Sales Order Item', 'prevdoc_docname', '=', frm.doc.name], ['Sales Order', 'docstatus', '<', 2]],
            fields: ['name'],
            limit: 1
        }).then(function(rows) {
            if (rows && rows.length) {
                frm.remove_custom_button('Sales Order', 'Create');
            }
        });
    }
});

frappe.ui.form.on('Solar Loan', {
    refresh: function(frm) {
        if (frm.is_new()) {
            return;
        }

        frappe.db.count('Site Visit', { filters: { related_loan: frm.doc.name } }).then(function(n) {
            if (n) {
                return;
            }
            frm.add_custom_button('Site Visit', function() {
                frappe.model.with_doctype('Site Visit', function() {
                    var d = frappe.model.get_new_doc('Site Visit');
                    d.customer = frm.doc.customer;
                    d.company = frm.doc.company;
                    d.phone = frm.doc.contact_no;
                    d.location_site_address = frm.doc.address;
                    d.related_loan = frm.doc.name;
                    d.quotation = frm.doc.quotation;
                    frappe.set_route('Form', 'Site Visit', d.name);
                });
            }, 'Create');
        });

        frm.add_custom_button('Set as Lost', function() {
            frappe.prompt([
                {
                    fieldname: 'lost_reason',
                    fieldtype: 'Small Text',
                    label: 'Reason',
                    reqd: 1
                }
            ], function(values) {
                frm.set_value('status', 'Lost');
                frm.set_value('lost_reason', values.lost_reason);
                frm.save();
            }, 'Set as Lost', 'Confirm');
        });
    }
});

frappe.ui.form.on('Site Visit', {
    refresh: function(frm) {
        if (frm.is_new()) {
            return;
        }

        var convert_lead = function() {
            frappe.call({
                method: 'erpnext.crm.doctype.lead.lead.make_customer',
                args: { source_name: frm.doc.custom_lead },
                freeze: true,
                freeze_message: 'Creating Customer from Lead ' + frm.doc.custom_lead,
                callback: function(r) {
                    if (!r.message) {
                        return;
                    }
                    var doc = frappe.model.sync(r.message)[0];
                    doc.lead_name = frm.doc.custom_lead;
                    frappe.set_route('Form', doc.doctype, doc.name);
                }
            });
        };

        // Lead not yet converted -> offer Create > Customer
        if (frm.doc.custom_lead && !frm.doc.customer) {
            frm.add_custom_button('Customer', convert_lead, 'Create');
        }

        // A quotation is already linked to this visit -> nothing to create
        if (frm.doc.quotation) {
            return;
        }

        frappe.db.count('Quotation', { filters: { custom_site_visit: frm.doc.name, docstatus: ['<', 2] } }).then(function(n) {
            if (n) {
                return;
            }
            frm.add_custom_button('Quotation', function() {
                // Quotation for the Customer when there is one, otherwise for the Lead,
                // using ERPNext's own mappers so party, contact and address are filled.
                var method, source;
                if (frm.doc.customer) {
                    method = 'erpnext.selling.doctype.customer.customer.make_quotation';
                    source = frm.doc.customer;
                } else if (frm.doc.custom_lead) {
                    method = 'erpnext.crm.doctype.lead.lead.make_quotation';
                    source = frm.doc.custom_lead;
                } else {
                    frappe.msgprint('Please set a Lead or a Customer first.');
                    return;
                }

                frappe.call({
                    method: method,
                    args: { source_name: source },
                    freeze: true,
                    freeze_message: 'Creating Quotation for ' + source,
                    callback: function(r) {
                        if (!r.message) {
                            return;
                        }
                        var doc = frappe.model.sync(r.message)[0];
                        doc.custom_site_visit = frm.doc.name;
                        if (frm.doc.custom_lead) {
                            doc.custom_lead = frm.doc.custom_lead;
                        }
                        if (frm.doc.company) {
                            doc.company = frm.doc.company;
                        }
                        frappe.set_route('Form', doc.doctype, doc.name);
                    }
                });
            }, 'Create');
        });
    }
});

// ===================================================================
// Product Delivery - totals, serial/batch selection, stock entry
// -------------------------------------------------------------------
// Serial/batch selections are stored as plain data on Product Delivery
// Item. They are handed to the Stock Entry via use_serial_batch_fields,
// which is the supported v16 path: ERPNext itself builds the Serial and
// Batch Bundle on submit. Product Delivery never touches Bin, SLE,
// Serial No or Batch records directly.
// ===================================================================

function pd_calculate(frm) {
    var total_qty = 0;
    var total_amount = 0;
    (frm.doc.items || []).forEach(function(row) {
        var qty = flt(row.qty);
        var rate = flt(row.rate);
        var amount = qty * rate;
        if (flt(row.amount) !== amount) {
            frappe.model.set_value(row.doctype, row.name, 'amount', amount);
        }
        total_qty += qty;
        total_amount += amount;
    });
    frm.set_value('total_qty', total_qty);
    frm.set_value('total_amount', total_amount);
}

// ---- selection helpers ------------------------------------------------

function pd_serial_list(row) {
    return String(row.serial_no || '')
        .split('\n')
        .map(function(s) { return s.trim(); })
        .filter(function(s) { return s.length; });
}

function pd_alloc_qty(row) {
    return (row.batch_allocation || []).reduce(function(a, b) { return a + flt(b.qty); }, 0);
}

function pd_row_warehouse(frm, row) {
    return row.s_warehouse || frm.doc.source_warehouse;
}

function pd_set_summary(frm, row) {
    var parts = [];
    var qty = flt(row.qty);

    if (row.has_serial_no) {
        var n = pd_serial_list(row).length;
        parts.push(n + ' / ' + qty + ' serial');
    }
    if (row.has_batch_no) {
        var a = pd_alloc_qty(row);
        parts.push(a + ' / ' + qty + ' in ' + (row.batch_allocation || []).length + ' batch');
    }

    var txt = parts.length ? parts.join('  \u00b7  ') : '';
    if (row.serial_batch_summary !== txt) {
        frappe.model.set_value(row.doctype, row.name, 'serial_batch_summary', txt);
    }
}

function pd_refresh_summaries(frm) {
    (frm.doc.items || []).forEach(function(row) { pd_set_summary(frm, row); });
}

// ---- availability -----------------------------------------------------
// Serial availability comes from the Serial No master's own warehouse and
// status fields, which ERPNext maintains. FIFO/LIFO order by creation,
// matching how ERPNext picks serials for an outward entry.

function pd_fetch_serials(item_code, warehouse, based_on) {
    return frappe.db.get_list('Serial No', {
        filters: { item_code: item_code, warehouse: warehouse, status: 'Active' },
        fields: ['name'],
        order_by: (based_on === 'LIFO') ? 'creation desc' : 'creation asc',
        limit: 500
    }).then(function(rows) {
        return (rows || []).map(function(r) { return r.name; });
    }).catch(function() { return []; });
}

// Batch availability is the summed ledger for that item in that warehouse,
// so already-consumed batches never appear.

function pd_fetch_batches(item_code, warehouse) {
    return frappe.db.get_list('Stock Ledger Entry', {
        filters: { item_code: item_code, warehouse: warehouse, is_cancelled: 0 },
        fields: ['batch_no', 'sum(actual_qty) as qty'],
        group_by: 'batch_no',
        limit: 500
    }).then(function(rows) {
        var avail = (rows || []).filter(function(r) {
            return r.batch_no && flt(r.qty) > 0;
        });
        if (!avail.length) { return []; }

        var names = avail.map(function(r) { return r.batch_no; });
        return frappe.db.get_list('Batch', {
            filters: { name: ['in', names] },
            fields: ['name', 'expiry_date', 'creation'],
            limit: 500
        }).then(function(meta) {
            var by_name = {};
            (meta || []).forEach(function(m) { by_name[m.name] = m; });
            return avail.map(function(r) {
                var m = by_name[r.batch_no] || {};
                return {
                    batch_no: r.batch_no,
                    qty: flt(r.qty),
                    expiry_date: m.expiry_date || null,
                    creation: m.creation || ''
                };
            });
        }).catch(function() {
            return avail.map(function(r) {
                return { batch_no: r.batch_no, qty: flt(r.qty), expiry_date: null, creation: '' };
            });
        });
    }).catch(function() {
        frappe.msgprint('Could not read batch availability from the stock ledger.');
        return [];
    });
}

function pd_sort_batches(list, based_on) {
    var out = list.slice();
    if (based_on === 'Expiry') {
        out.sort(function(a, b) {
            if (!a.expiry_date) { return 1; }
            if (!b.expiry_date) { return -1; }
            return a.expiry_date < b.expiry_date ? -1 : 1;
        });
    } else if (based_on === 'LIFO') {
        out.sort(function(a, b) { return a.creation < b.creation ? 1 : -1; });
    } else {
        out.sort(function(a, b) { return a.creation < b.creation ? -1 : 1; });
    }
    return out;
}

// ---- selector dialog --------------------------------------------------

function pd_open_selector(frm, cdt, cdn) {
    var row = locals[cdt][cdn];

    if (!row.item_code) {
        frappe.msgprint('Pick an Item Code first.');
        return;
    }
    if (flt(row.qty) <= 0) {
        frappe.msgprint('Enter a Transfer Qty first.');
        return;
    }

    var warehouse = pd_row_warehouse(frm, row);
    if (!warehouse) {
        frappe.msgprint('Set the Source Warehouse first. Serial and batch availability is read from it.');
        return;
    }
    if (!row.has_serial_no && !row.has_batch_no) {
        frappe.msgprint('This item is not serial or batch tracked.');
        return;
    }

    var qty = flt(row.qty);
    var fields = [{ fieldtype: 'HTML', fieldname: 'ctx' }];

    if (row.has_serial_no) {
        fields.push({ fieldtype: 'Section Break', label: 'Auto Fetch' });
        fields.push({ fieldtype: 'Float', fieldname: 's_qty', label: 'Qty to Fetch', default: qty });
        fields.push({ fieldtype: 'Column Break' });
        fields.push({ fieldtype: 'Select', fieldname: 's_based_on', label: 'Fetch Based On', options: 'FIFO\nLIFO', default: 'FIFO' });
        fields.push({ fieldtype: 'Column Break' });
        fields.push({ fieldtype: 'Button', fieldname: 's_fetch', label: 'Fetch' });
        fields.push({ fieldtype: 'Section Break', label: 'Serial No' });
        fields.push({ fieldtype: 'HTML', fieldname: 's_area' });
    }

    if (row.has_batch_no) {
        fields.push({ fieldtype: 'Section Break', label: 'Batch Auto Fetch' });
        fields.push({ fieldtype: 'Float', fieldname: 'b_qty', label: 'Qty to Fetch', default: qty });
        fields.push({ fieldtype: 'Column Break' });
        fields.push({ fieldtype: 'Select', fieldname: 'b_based_on', label: 'Fetch Based On', options: 'FIFO\nLIFO\nExpiry', default: 'FIFO' });
        fields.push({ fieldtype: 'Column Break' });
        fields.push({ fieldtype: 'Button', fieldname: 'b_fetch', label: 'Fetch' });
        fields.push({ fieldtype: 'Section Break', label: 'Batch' });
        fields.push({ fieldtype: 'HTML', fieldname: 'b_area' });
    }

    var serials_avail = [];
    var batches_avail = [];

    var d = new frappe.ui.Dialog({
        title: 'Select Serial / Batch',
        size: 'large',
        fields: fields,
        primary_action_label: 'Confirm Selection',
        primary_action: function() { pd_apply_selection(frm, row, d); }
    });

    d.fields_dict.ctx.$wrapper.html(
        '<div style="display:flex;gap:24px;font-size:12px;padding:2px 0 4px;">' +
        '<div><div style="color:var(--text-muted);">Item Code</div><b>' + frappe.utils.escape_html(row.item_code) + '</b></div>' +
        '<div><div style="color:var(--text-muted);">Warehouse</div><b>' + frappe.utils.escape_html(warehouse) + '</b></div>' +
        '<div><div style="color:var(--text-muted);">Required Qty</div><b>' + qty + '</b></div>' +
        '</div>'
    );

    // ---- serial rendering ----
    function render_serials(checked) {
        var chosen = checked || {};
        var html = '<div style="max-height:260px;overflow:auto;border:1px solid var(--border-color);border-radius:6px;padding:8px;">';

        if (!serials_avail.length) {
            html += '<div style="color:var(--text-muted);font-size:12px;">No active serial numbers in ' + frappe.utils.escape_html(warehouse) + '.</div>';
        } else {
            html += '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:4px;">';
            serials_avail.forEach(function(sn) {
                html += '<label class="checkbox" style="margin:0;font-size:12px;">' +
                        '<input type="checkbox" class="pd-sn" value="' + frappe.utils.escape_html(sn) + '"' +
                        (chosen[sn] ? ' checked' : '') + '> ' + frappe.utils.escape_html(sn) + '</label>';
            });
            html += '</div>';
        }
        html += '</div><div class="pd-sn-count" style="font-size:12px;margin-top:6px;"></div>';

        d.fields_dict.s_area.$wrapper.html(html);
        d.fields_dict.s_area.$wrapper.find('.pd-sn').on('change', update_sn_count);
        update_sn_count();
    }

    function update_sn_count() {
        var n = d.fields_dict.s_area.$wrapper.find('.pd-sn:checked').length;
        var ok = (n === qty);
        d.fields_dict.s_area.$wrapper.find('.pd-sn-count').html(
            '<span style="color:' + (ok ? 'var(--green-600,#16a34a)' : 'var(--orange-600,#ea580c)') + ';font-weight:600;">' +
            n + ' of ' + qty + ' selected</span>'
        );
    }

    function load_serials(based_on) {
        d.fields_dict.s_area.$wrapper.html('<div style="font-size:12px;color:var(--text-muted);">Loading serial numbers\u2026</div>');
        return pd_fetch_serials(row.item_code, warehouse, based_on).then(function(list) {
            serials_avail = list;
            var pre = {};
            pd_serial_list(row).forEach(function(sn) {
                pre[sn] = true;
                if (list.indexOf(sn) === -1) { serials_avail.push(sn); }
            });
            render_serials(pre);
        });
    }

    // ---- batch rendering ----
    function render_batches(alloc) {
        var chosen = alloc || {};
        var html = '<div style="border:1px solid var(--border-color);border-radius:6px;overflow:hidden;">';

        if (!batches_avail.length) {
            html += '<div style="padding:10px;color:var(--text-muted);font-size:12px;">No batches with stock in ' + frappe.utils.escape_html(warehouse) + '.</div>';
        } else {
            html += '<table class="table table-bordered" style="margin:0;font-size:12px;">' +
                    '<thead><tr><th>Batch No</th><th style="width:110px;">Available</th><th style="width:110px;">Expiry</th><th style="width:130px;">Qty to Transfer</th></tr></thead><tbody>';
            batches_avail.forEach(function(b) {
                html += '<tr>' +
                    '<td>' + frappe.utils.escape_html(b.batch_no) + '</td>' +
                    '<td>' + b.qty + '</td>' +
                    '<td>' + (b.expiry_date ? frappe.datetime.str_to_user(b.expiry_date) : '\u2013') + '</td>' +
                    '<td><input type="number" class="form-control input-sm pd-bq" min="0" step="any" ' +
                    'data-batch="' + frappe.utils.escape_html(b.batch_no) + '" data-avail="' + b.qty + '" ' +
                    'value="' + (chosen[b.batch_no] || 0) + '" style="height:26px;"></td>' +
                    '</tr>';
            });
            html += '</tbody></table>';
        }
        html += '</div><div class="pd-bq-count" style="font-size:12px;margin-top:6px;"></div>';

        d.fields_dict.b_area.$wrapper.html(html);
        d.fields_dict.b_area.$wrapper.find('.pd-bq').on('input', update_bq_count);
        update_bq_count();
    }

    function update_bq_count() {
        var total = 0;
        var over = false;
        d.fields_dict.b_area.$wrapper.find('.pd-bq').each(function() {
            var v = flt($(this).val());
            var avail = flt($(this).data('avail'));
            if (v > avail) { over = true; }
            total += v;
        });
        var ok = (total === qty) && !over;
        var msg = total + ' of ' + qty + ' allocated';
        if (over) { msg += '  \u00b7  a batch is over its available qty'; }
        d.fields_dict.b_area.$wrapper.find('.pd-bq-count').html(
            '<span style="color:' + (ok ? 'var(--green-600,#16a34a)' : 'var(--orange-600,#ea580c)') + ';font-weight:600;">' + msg + '</span>'
        );
    }

    function load_batches(based_on) {
        d.fields_dict.b_area.$wrapper.html('<div style="font-size:12px;color:var(--text-muted);">Loading batches\u2026</div>');
        return pd_fetch_batches(row.item_code, warehouse).then(function(list) {
            batches_avail = pd_sort_batches(list, based_on);
            var pre = {};
            (row.batch_allocation || []).forEach(function(b) {
                if (b.batch_no) { pre[b.batch_no] = flt(b.qty); }
            });
            render_batches(pre);
        });
    }

    // ---- auto fetch handlers ----
    if (row.has_serial_no) {
        d.fields_dict.s_fetch.$input.on('click', function() {
            var want = flt(d.get_value('s_qty'));
            var based_on = d.get_value('s_based_on');
            load_serials(based_on).then(function() {
                var pick = {};
                serials_avail.slice(0, want).forEach(function(sn) { pick[sn] = true; });
                render_serials(pick);
            });
        });
    }

    if (row.has_batch_no) {
        d.fields_dict.b_fetch.$input.on('click', function() {
            var want = flt(d.get_value('b_qty'));
            var based_on = d.get_value('b_based_on');
            load_batches(based_on).then(function() {
                var left = want;
                var pick = {};
                batches_avail.forEach(function(b) {
                    if (left <= 0) { return; }
                    var take = Math.min(left, b.qty);
                    pick[b.batch_no] = take;
                    left -= take;
                });
                if (left > 0) {
                    frappe.msgprint('Only ' + (want - left) + ' of ' + want + ' is available across all batches in ' + warehouse + '.');
                }
                render_batches(pick);
            });
        });
    }

    d.show();

    if (row.has_serial_no) { load_serials('FIFO'); }
    if (row.has_batch_no) { load_batches('FIFO'); }
}

function pd_apply_selection(frm, row, d) {
    var qty = flt(row.qty);

    if (row.has_serial_no) {
        var picked = [];
        d.fields_dict.s_area.$wrapper.find('.pd-sn:checked').each(function() {
            picked.push($(this).val());
        });
        if (picked.length !== qty) {
            frappe.msgprint((row.item_name || row.item_code) + ' requires ' + qty +
                ' serial number(s), but ' + picked.length + ' selected.');
            return;
        }
        frappe.model.set_value(row.doctype, row.name, 'serial_no', picked.join('\n'));
    }

    if (row.has_batch_no) {
        var allocs = [];
        var total = 0;
        var over = null;
        d.fields_dict.b_area.$wrapper.find('.pd-bq').each(function() {
            var v = flt($(this).val());
            if (v <= 0) { return; }
            var batch = $(this).data('batch');
            var avail = flt($(this).data('avail'));
            if (v > avail) { over = batch; }
            total += v;
            allocs.push({ batch_no: batch, qty: v, available_qty: avail });
        });

        if (over) {
            frappe.msgprint('Batch ' + over + ' does not have that much stock available.');
            return;
        }
        if (total !== qty) {
            frappe.msgprint((row.item_name || row.item_code) + ' requires ' + qty +
                ' allocated across batches, but ' + total + ' allocated.');
            return;
        }

        frappe.model.clear_table(row, 'batch_allocation');
        allocs.forEach(function(a) {
            var c = frappe.model.add_child(row, 'Product Delivery Batch Allocation', 'batch_allocation');
            c.batch_no = a.batch_no;
            c.qty = a.qty;
            c.available_qty = a.available_qty;
        });
        // Keep the legacy single-batch field meaningful when there is only one.
        frappe.model.set_value(row.doctype, row.name, 'batch_no',
            allocs.length === 1 ? allocs[0].batch_no : null);
        frm.refresh_field('items');
    }

    pd_set_summary(frm, row);
    frm.refresh_field('items');
    d.hide();
}

// ---- validation gate --------------------------------------------------

function pd_tracking_errors(frm) {
    var errors = [];

    (frm.doc.items || []).forEach(function(row) {
        if (!row.is_stock_item) { return; }
        var qty = flt(row.qty);
        if (qty <= 0) { return; }
        var label = row.item_name || row.item_code;

        if (row.has_serial_no) {
            var n = pd_serial_list(row).length;
            if (n !== qty) {
                errors.push(label + ' requires ' + qty + ' serial number(s), but ' + n +
                    ' serial number(s) have been selected.');
            }
        }
        if (row.has_batch_no) {
            var a = pd_alloc_qty(row);
            if (a !== qty) {
                errors.push(label + ' requires ' + qty + ' allocated across batches, but ' + a +
                    ' has been allocated.');
            }
        }
    });

    return errors;
}

