function inst_calculate(frm) {
    var t = 0, u = 0, b = 0;
    (frm.doc.materials || []).forEach(function(row) {
        var tq = flt(row.transferred_qty);
        var uq = flt(row.used_qty);
        if (uq > tq) {
            uq = tq;
            frappe.model.set_value(row.doctype, row.name, 'used_qty', uq);
        }
        var bal = tq - uq;
        if (flt(row.balance_qty) !== bal) {
            frappe.model.set_value(row.doctype, row.name, 'balance_qty', bal);
        }
        t += tq; u += uq; b += bal;
    });
    frm.set_value('total_transferred_qty', t);
    frm.set_value('total_used_qty', u);
    frm.set_value('total_balance_qty', b);
}

// Builds the Material Issue stock entry from whatever is in used_qty.
function inst_build_issue(frm) {
    var project_name = frm.doc.project;

    frappe.model.with_doctype('Stock Entry', function() {
        var se = frappe.model.get_new_doc('Stock Entry');
        se.stock_entry_type = 'Material Issue';
        se.purpose = 'Material Issue';
        se.company = frm.doc.company;
        se.installation = frm.doc.name;
        se.project = project_name;
        se.custom_projects = project_name;
        se.from_warehouse = frm.doc.site_warehouse;

        (frm.doc.materials || []).forEach(function(row) {
            if (flt(row.used_qty) <= 0) { return; }
            var d = frappe.model.add_child(se, 'Stock Entry Detail', 'items');
            d.item_code = row.item_code;
            d.qty = flt(row.used_qty);
            d.uom = row.uom;
            d.stock_uom = row.uom;
            d.conversion_factor = 1;
            d.s_warehouse = frm.doc.site_warehouse;
            d.project = project_name;
            if (row.batch_no) { d.batch_no = row.batch_no; }
            if (row.serial_no) { d.serial_no = row.serial_no; }
        });

        frappe.set_route('Form', 'Stock Entry', se.name);
        setTimeout(function() {
            if (cur_frm && cur_frm.doc && cur_frm.doc.name === se.name) {
                if (!cur_frm.doc.installation) { cur_frm.set_value('installation', frm.doc.name); }
                if (project_name && !cur_frm.doc.custom_projects) { cur_frm.set_value('custom_projects', project_name); }
                cur_frm.refresh_fields();
            }
        }, 600);
    });
}

// Asks for the quantity actually used at site when nothing has been entered yet,
// writes it back to the Material tab, saves, then builds the stock entry.
function inst_ask_qty(frm) {
    var rows = (frm.doc.materials || []).filter(function(r) { return flt(r.balance_qty) > 0; });

    if (!rows.length) {
        frappe.msgprint('There is no material left to issue on this installation.');
        return;
    }

    var fields = [{
        fieldtype: 'HTML',
        options: '<div style="font-size:12px;color:var(--text-muted);margin-bottom:6px;">Enter how much of each item was actually consumed at site. This is written back to the Material tab before the stock entry is created.</div>'
    }];

    rows.forEach(function(r, i) {
        fields.push({
            fieldtype: 'Float',
            fieldname: 'q' + i,
            label: (r.item_name || r.item_code) + '  \u00b7  available ' + flt(r.balance_qty) + ' ' + (r.uom || ''),
            default: flt(r.balance_qty)
        });
    });

    var d = new frappe.ui.Dialog({
        title: 'Quantity Used at Site',
        fields: fields,
        primary_action_label: 'Create Material Issue',
        primary_action: function(v) {
            var any = false;
            var jobs = rows.map(function(r, i) {
                var q = flt(v['q' + i]);
                if (q < 0) { q = 0; }
                if (q > flt(r.balance_qty)) { q = flt(r.balance_qty); }
                if (q > 0) { any = true; }
                return frappe.model.set_value(r.doctype, r.name, 'used_qty', q);
            });

            if (!any) {
                frappe.msgprint('Enter a quantity for at least one item.');
                return;
            }

            d.hide();

            Promise.all(jobs).then(function() {
                inst_calculate(frm);
                return frm.save();
            }).then(function() {
                inst_build_issue(frm);
            }).catch(function() {
                frappe.msgprint('Could not save the used quantities. Fix any errors on the form and try again.');
            });
        }
    });

    d.show();
}

