function proj_costs(frm) {
    var other = flt(frm.doc.total_costing_amount)
        + flt(frm.doc.total_expense_claim)
        + flt(frm.doc.total_purchase_cost)
        + flt(frm.doc.total_consumed_material_cost)
        + flt(frm.doc.custom_miscellaneous_expense);

    frm.set_value('custom_total_other_costs', other);
    frm.set_value('custom_total_cost', other);

    var estimated = flt(frm.doc.estimated_costing);
    frm.set_value('custom_budget_remaining', estimated - other);
    frm.set_value('custom_budget_used_percent', estimated > 0 ? (other / estimated) * 100 : 0);
}

