// Installation.total_project_cost has no fetch_from and nothing else writes to
// it, so it would otherwise sit at 0. It mirrors the Project's Total Cost
// (custom_total_cost) exactly.
//
// The component list below is deliberately identical to the one in the
// 'Project - Total Cost Live Calculation' script. Do NOT add
// custom_total_other_costs or custom_total_cost here - those are the SUM of
// these components, so including them double counts the whole total.
//
// The Project doc is read whole rather than via an explicit field list,
// because a list breaks entirely if one field is absent on the site (for
// example total_expense_claim, which only exists when HRMS is installed).

var INST_COST_COMPONENTS = [
    'total_costing_amount',
    'total_expense_claim',
    'total_purchase_cost',
    'total_consumed_material_cost',
    'custom_miscellaneous_expense'
];

function inst_fetch_project_cost(frm, cb) {
    if (!frm.doc.project) {
        cb(0);
        return;
    }

    frappe.db.get_doc('Project', frm.doc.project).then(function(p) {
        if (!p) { cb(flt(frm.doc.total_project_cost)); return; }

        // Recompute from components so the figure is right even if nobody has
        // opened and saved the Project since the last cost was booked.
        var live = 0;
        INST_COST_COMPONENTS.forEach(function(f) {
            if (p[f] !== undefined && p[f] !== null) { live += flt(p[f]); }
        });

        // Fall back to the stored Total Cost if no component carries a value.
        cb(live > 0 ? live : flt(p.custom_total_cost));
    }).catch(function() {
        cb(flt(frm.doc.total_project_cost));
    });
}

function inst_show_project_cost(frm) {
    inst_fetch_project_cost(frm, function(cost) {
        frm.__project_cost = cost;

        // Update the display without dirtying the form, so simply opening an
        // Installation never leaves it in a 'Not Saved' state.
        if (flt(frm.doc.total_project_cost) !== flt(cost)) {
            frm.doc.total_project_cost = cost;
            frm.refresh_field('total_project_cost');
        }
    });
}

