/* ---------- helpers ---------------------------------------------------- */

function esc(v) {
    if (v === null || v === undefined) { return ""; }
    return String(v).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;").replace(/'/g, "&#039;");
}

function fdate(v) {
    if (!v) { return "\u2014"; }
    try { return frappe.datetime.str_to_user(String(v).slice(0, 10)); } catch (e) { return v; }
}

function days_between(target, today) {
    try { return frappe.datetime.get_diff(target, today); } catch (e) { return null; }
}

function dur(sec) {
    if (!sec) { return "\u2014"; }
    var s = Math.round(sec), h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60);
    if (h >= 24) { return Math.floor(h / 24) + "d " + (h % 24) + "h"; }
    if (h) { return h + "h " + m + "m"; }
    return m + "m";
}

function assignee(v, fallback) {
    if (v) {
        try {
            var list = JSON.parse(v);
            if (list && list.length) { return list.join(", "); }
        } catch (e) { /* not json */ }
    }
    return fallback ? fallback : "\u2014";
}

// Reading a child table needs the parent doctype named, for permission checks.
// Frappe v16 calls that argument parent_doctype; older builds called it parent.
// Try the current name, fall back to the old one, give up quietly.
function child_rows(child_dt, parent_dt, opts) {
    var modern = Object.assign({}, opts);
    modern.parent_doctype = parent_dt;

    return frappe.db.get_list(child_dt, modern).catch(function () {
        var legacy = Object.assign({}, opts);
        legacy.parent = parent_dt;
        return frappe.db.get_list(child_dt, legacy).catch(function () { return []; });
    });
}

/* ---------- data ------------------------------------------------------- */

function csc_threshold() {
    return frappe.db.get_value("Support Settings", "Support Settings", "custom_expiring_soon_days")
        .then(function (r) {
            var v = (r && r.message) ? cint(r.message.custom_expiring_soon_days) : 0;
            return v > 0 ? v : EXPIRING_DEFAULT;
        })
        .catch(function () { return EXPIRING_DEFAULT; });
}

// Serials reach a customer two ways: the custom_customer link stamped by the
// Material Issue flow, and ERPNext's own customer field set on delivery.
// Both are read and merged so nothing is missed.
function csc_serials(customer) {
    var fields = ["name", "item_code", "item_name", "status", "custom_consumed_date",
        "warranty_expiry_date", "custom_amc_start_date", "amc_expiry_date",
        "custom_installation", "custom_project"];
    var merged = {};

    var run = function (field) {
        var filters = {};
        filters[field] = customer;
        return frappe.db.get_list("Serial No", {
            filters: filters, fields: fields, order_by: "creation desc", limit: 200
        }).then(function (rows) {
            (rows || []).forEach(function (r) { merged[r.name] = r; });
        }).catch(function () { /* field absent on this build */ });
    };

    return Promise.all([run("custom_customer"), run("customer")]).then(function () {
        return Object.keys(merged).map(function (k) { return merged[k]; });
    });
}

function csc_fetch(customer) {
    return Promise.all([
        csc_threshold(),
        csc_serials(customer),
        frappe.db.get_list("Maintenance Schedule", {
            filters: { customer: customer },
            fields: ["name", "status", "transaction_date", "docstatus", "modified"],
            order_by: "transaction_date desc", limit: 50
        }).catch(function () { return []; }),
        frappe.db.get_list("Maintenance Visit", {
            filters: { customer: customer },
            fields: ["name", "mntc_date", "maintenance_type", "completion_status",
                     "status", "docstatus", "maintenance_schedule", "modified"],
            order_by: "mntc_date desc", limit: 50
        }).catch(function () { return []; }),
        frappe.db.get_list("Issue", {
            filters: { customer: customer },
            fields: ["name", "subject", "status", "priority", "opening_date",
                     "issue_type", "modified", "_assign", "first_responded_on",
                     "first_response_time", "response_by", "agreement_status",
                     "resolution_time"],
            order_by: "modified desc", limit: 50
        }).catch(function () { return []; }),
        // Warranty Claim has no priority field on this install, so the
        // Warranty / AMC status is carried instead. resolved_by backs up _assign.
        frappe.db.get_list("Warranty Claim", {
            filters: { customer: customer },
            fields: ["name", "serial_no", "item_code", "item_name", "status",
                     "complaint_date", "warranty_amc_status", "resolution_date",
                     "resolved_by", "modified", "_assign"],
            order_by: "complaint_date desc", limit: 50
        }).catch(function () { return []; }),
        frappe.db.get_list("Installation", {
            filters: { customer: customer },
            fields: ["name", "installation_status", "scheduled_date", "modified"],
            order_by: "modified desc", limit: 10
        }).catch(function () { return []; }),
        frappe.db.get_list("Project Commission", {
            filters: { customer: customer },
            fields: ["name", "status_of_project_commission", "modified"],
            order_by: "modified desc", limit: 10
        }).catch(function () { return []; })
    ]).then(function (res) {
        var d = {
            threshold: res[0], serials: res[1], schedules: res[2], visits: res[3],
            issues: res[4], claims: res[5], installs: res[6], commissions: res[7],
            details: [], purposes: [], ledger: []
        };

        var jobs = [];

        // Maintenance Schedule Detail holds the actual planned dates, which is
        // what pending / upcoming / overdue must be derived from.
        var live = d.schedules.filter(function (s) { return s.docstatus !== 2; })
            .map(function (s) { return s.name; });
        if (live.length) {
            jobs.push(child_rows("Maintenance Schedule Detail", "Maintenance Schedule", {
                filters: { parent: ["in", live], parenttype: "Maintenance Schedule" },
                fields: ["name", "parent", "item_code", "item_name", "serial_no",
                         "scheduled_date", "actual_date", "completion_status", "sales_person"],
                order_by: "scheduled_date asc", limit: 300
            }).then(function (rows) { d.details = rows || []; }));
        }

        var vnames = d.visits.map(function (v) { return v.name; });
        if (vnames.length) {
            jobs.push(child_rows("Maintenance Visit Purpose", "Maintenance Visit", {
                filters: { parent: ["in", vnames], parenttype: "Maintenance Visit" },
                fields: ["parent", "item_code", "item_name", "serial_no", "service_person"],
                limit: 300
            }).then(function (rows) { d.purposes = rows || []; }));
        }

        // Serial ledger. The standard Serial No Ledger report is a Script
        // Report keyed on a single serial_no with no customer filter, so it
        // cannot be embedded customer-wide. The same movements are read from
        // the Serial and Batch Bundle, which is where ERPNext records them,
        // scoped to this customer's serials only.
        var snames = d.serials.map(function (s) { return s.name; });
        if (snames.length) {
            jobs.push(child_rows("Serial and Batch Entry", "Serial and Batch Bundle", {
                filters: { serial_no: ["in", snames] },
                fields: ["parent", "serial_no", "qty", "warehouse"],
                limit: 400
            }).then(function (entries) {
                var parents = [];
                (entries || []).forEach(function (e) {
                    if (parents.indexOf(e.parent) === -1) { parents.push(e.parent); }
                });
                if (!parents.length) { return; }

                return frappe.db.get_list("Serial and Batch Bundle", {
                    filters: { name: ["in", parents], is_cancelled: 0 },
                    fields: ["name", "item_code", "item_name", "warehouse", "voucher_type",
                             "voucher_no", "posting_datetime", "type_of_transaction"],
                    limit: 400
                }).then(function (bundles) {
                    var bmap = {};
                    (bundles || []).forEach(function (b) { bmap[b.name] = b; });
                    d.ledger = (entries || []).filter(function (e) { return bmap[e.parent]; })
                        .map(function (e) {
                            var b = bmap[e.parent];
                            return {
                                date: b.posting_datetime, item_code: b.item_code,
                                item_name: b.item_name, serial_no: e.serial_no,
                                type: b.type_of_transaction,
                                voucher_type: b.voucher_type, voucher_no: b.voucher_no,
                                warehouse: e.warehouse || b.warehouse, qty: e.qty
                            };
                        })
                        .sort(function (a, b) { return String(b.date).localeCompare(String(a.date)); });
                }).catch(function () { d.ledger = []; });
            }));
        }

        return Promise.all(jobs).then(function () { return d; });
    });
}

/* ---------- derivations ------------------------------------------------ */

// Recomputed live rather than trusting the stored status, which only updates
// when a Serial No is saved and so can lag behind the calendar.
function warranty_state(expiry, today, threshold) {
    if (!expiry) { return { key: "none", label: "No Warranty", days: null }; }
    var diff = days_between(expiry, today);
    if (diff === null) { return { key: "none", label: "No Warranty", days: null }; }
    if (diff < 0) { return { key: "expired", label: "Expired", days: diff }; }
    if (diff <= threshold) { return { key: "expiring", label: "Expiring Soon", days: diff }; }
    return { key: "active", label: "Active", days: diff };
}

function days_text(state) {
    if (state.key === "none") { return "\u2014"; }
    if (state.key === "expired") { return "Expired"; }
    if (state.days === 0) { return "Today"; }
    return state.days + " days";
}

// A planned maintenance row is only overdue if it is past due AND not done.
function detail_state(row, today) {
    var done = row.completion_status === "Fully Completed" || !!row.actual_date;
    if (done) { return { key: "completed", label: "Completed" }; }
    if (row.completion_status === "Partially Completed") {
        if (row.scheduled_date && days_between(row.scheduled_date, today) < 0) {
            return { key: "overdue", label: "Overdue" };
        }
        return { key: "pending", label: "Partially Completed" };
    }
    if (row.scheduled_date && days_between(row.scheduled_date, today) < 0) {
        return { key: "overdue", label: "Overdue" };
    }
    return { key: "upcoming", label: "Upcoming" };
}

// Maintenance Visit has no scheduled/completed status of its own - only
// docstatus and completion_status - so the display status is derived.
function visit_state(v, today) {
    if (v.docstatus === 2 || v.status === "Cancelled") { return { key: "cancelled", label: "Cancelled" }; }
    if (v.completion_status === "Fully Completed") { return { key: "completed", label: "Completed" }; }
    var late = v.mntc_date && days_between(v.mntc_date, today) < 0;
    if (v.completion_status === "Partially Completed") {
        return late ? { key: "overdue", label: "Overdue" } : { key: "pending", label: "Partially Completed" };
    }
    if (late) { return { key: "overdue", label: "Overdue" }; }
    if (v.docstatus === 0) { return { key: "pending", label: "Draft" }; }
    return { key: "scheduled", label: "Scheduled" };
}

function issue_bucket(status) {
    if (status === "Open") { return "open"; }
    if (status === "Replied" || status === "On Hold") { return "progress"; }
    if (status === "Resolved") { return "resolved"; }
    if (status === "Closed") { return "closed"; }
    return "open";
}

// The Warranty Claim workflow on this install is Open / Work In Progress /
// Closed / Cancelled. There is no Pending or Resolved state, so Closed is
// treated as the resolved terminal state rather than inventing categories.
function claim_bucket(status) {
    if (status === "Open") { return "open"; }
    if (status === "Work In Progress") { return "progress"; }
    if (status === "Closed") { return "closed"; }
    if (status === "Cancelled") { return "cancelled"; }
    return "open";
}

function priority_key(p) {
    var v = String(p || "").toLowerCase();
    if (v === "urgent" || v === "critical") { return "urgent"; }
    if (v === "high") { return "high"; }
    if (v === "medium") { return "medium"; }
    return "low";
}

/* ---------- load ------------------------------------------------------- */

function csc_load(frm) {
    var field = frm.fields_dict["custom_support_center_html"];
    if (!field) { return; }

    var customer = frm.doc.name;
    field.$wrapper.html("<style>" + CSC_CSS + "</style>" +
        "<div class='csc-container'><div class='csc-loading'>Loading Support Center\u2026</div></div>");

    csc_fetch(customer).then(function (data) {
        csc_render(frm, field, customer, data);
    }).catch(function (e) {
        console.error("Support Center failed", e);
        field.$wrapper.html("<style>" + CSC_CSS + "</style>" +
            "<div class='csc-container'><div class='csc-error'>" +
            "<div class='csc-error-msg'>Unable to load Support Center data. Please try again.</div>" +
            "<button class='csc-btn csc-retry'>Retry</button></div></div>");
        field.$wrapper.find(".csc-retry").on("click", function () { csc_load(frm); });
    });
}

/* ---------- render ----------------------------------------------------- */

function csc_render(frm, field, customer, d) {
    var today = frappe.datetime.get_today();
    var T = d.threshold;

    // warranty
    var warranty = d.serials.map(function (s) {
        return { s: s, w: warranty_state(s.warranty_expiry_date, today, T),
                 a: warranty_state(s.amc_expiry_date, today, T) };
    });
    var w_items = warranty.filter(function (r) { return r.w.key !== "none"; });
    var w_active = w_items.filter(function (r) { return r.w.key === "active"; }).length;
    var w_expiring = w_items.filter(function (r) { return r.w.key === "expiring"; }).length;
    var w_expired = w_items.filter(function (r) { return r.w.key === "expired"; }).length;

    // claims
    var c_by = function (k) {
        return d.claims.filter(function (c) { return claim_bucket(c.status) === k; }).length;
    };
    var c_open = c_by("open"), c_prog = c_by("progress"),
        c_closed = c_by("closed"), c_cancelled = c_by("cancelled");

    // maintenance (planned rows)
    var details = d.details.map(function (r) { return { r: r, st: detail_state(r, today) }; });
    var m_completed = details.filter(function (x) { return x.st.key === "completed"; }).length;
    var m_overdue = details.filter(function (x) { return x.st.key === "overdue"; }).length;
    var m_upcoming = details.filter(function (x) { return x.st.key === "upcoming"; }).length;
    var m_pending = details.filter(function (x) { return x.st.key !== "completed"; }).length;
    var upcoming = details.filter(function (x) { return x.st.key === "upcoming"; })
        .sort(function (a, b) { return a.r.scheduled_date < b.r.scheduled_date ? -1 : 1; });
    var next_visit = upcoming.length ? upcoming[0] : null;

    // visits
    var visits = d.visits.map(function (v) { return { v: v, st: visit_state(v, today) }; });
    var v_by = function (k) { return visits.filter(function (x) { return x.st.key === k; }).length; };

    // issues
    var i_open = d.issues.filter(function (i) { return issue_bucket(i.status) === "open"; }).length;
    var i_prog = d.issues.filter(function (i) { return issue_bucket(i.status) === "progress"; }).length;
    var i_res = d.issues.filter(function (i) { return issue_bucket(i.status) === "resolved"; }).length;
    var i_closed = d.issues.filter(function (i) { return issue_bucket(i.status) === "closed"; }).length;
    var urgent_open = d.issues.filter(function (i) {
        var k = priority_key(i.priority);
        return issue_bucket(i.status) === "open" && (k === "urgent" || k === "high");
    }).length;

    // first response
    var responded = d.issues.filter(function (i) { return i.first_responded_on; });
    var avg_first = null;
    var timed = responded.filter(function (i) { return i.first_response_time; });
    if (timed.length) {
        avg_first = timed.reduce(function (a, i) { return a + flt(i.first_response_time); }, 0) / timed.length;
    }

    // overall status - open claims count toward attention
    var support_status, support_key;
    if (m_overdue > 0 || w_expired > 0 || urgent_open > 0 || v_by("overdue") > 0 || c_open > 0) {
        support_status = "Attention Required"; support_key = "orange";
    } else if (d.serials.length || w_active || m_pending || i_open || i_prog) {
        support_status = "Active"; support_key = "green";
    } else {
        support_status = "No Active Support"; support_key = "grey";
    }

    var commissioned = d.commissions.some(function (c) {
        return String(c.status_of_project_commission || "").toLowerCase() === "commissioned";
    });

    var last_activity = null;
    [].concat(d.visits, d.issues, d.claims, d.installs, d.commissions).forEach(function (r) {
        if (r && r.modified && (!last_activity || r.modified > last_activity)) { last_activity = r.modified; }
    });

    /* header */
    var html = "<style>" + CSC_CSS + "</style><div class='csc-container'>";

    html += "<div class='csc-header'>" +
        "<div class='csc-header-title'><div class='csc-main-title'>Support Center</div>" +
        "<div class='csc-subtitle'>Manage warranty, claims, maintenance, service visits and customer support.</div></div>" +
        "<div class='csc-header-item'><div class='csc-label'>Support Status</div>" +
        "<div class='csc-current'><span class='csc-dot csc-dot-" + support_key + "'></span>" + esc(support_status) + "</div></div>" +
        "<div class='csc-header-item'><div class='csc-label'>Customer</div><div class='csc-value'>" + esc(customer) + "</div></div>" +
        "<div class='csc-header-item'><div class='csc-label'>Installed Products</div><div class='csc-value'>" + d.serials.length + "</div></div>" +
        "<div class='csc-header-item'><div class='csc-label'>Last Activity</div><div class='csc-value'>" + fdate(last_activity) + "</div>" +
        "<button class='csc-btn csc-refresh'>Refresh</button></div>" +
        "</div>";

    if (!commissioned) {
        html += "<div class='csc-note'>Project commissioning not completed for this customer. " +
                "Support records below reflect whatever exists so far.</div>";
    }

    /* summary cards */
    var cards = [
        { label: "Warranty Items", value: w_items.length, key: "blue", dt: "Serial No", f: { custom_customer: customer } },
        { label: "Active Warranties", value: w_active, key: "green", dt: "Serial No", f: { custom_customer: customer } },
        { label: "Expiring Soon", value: w_expiring, key: "orange", dt: "Serial No", f: { custom_customer: customer } },
        { label: "Expired", value: w_expired, key: "red", dt: "Serial No", f: { custom_customer: customer } },
        { label: "Maintenance Pending", value: m_pending, key: "orange", dt: "Maintenance Schedule", f: { customer: customer } },
        { label: "Maintenance Completed", value: m_completed, key: "green", dt: "Maintenance Schedule", f: { customer: customer } },
        { label: "Maintenance Overdue", value: m_overdue, key: "red", dt: "Maintenance Schedule", f: { customer: customer } },
        { label: "Open Issues", value: i_open, key: "orange", dt: "Issue", f: { customer: customer, status: "Open" } },
        { label: "Replied", value: i_prog, key: "blue", dt: "Issue", f: { customer: customer, status: "Replied" } },
        { label: "Resolved", value: i_res, key: "green", dt: "Issue", f: { customer: customer, status: "Resolved" } }
    ];

    html += "<div class='csc-cards'>";
    cards.forEach(function (c, i) {
        html += "<div class='csc-card csc-c-" + c.key + "' data-card='" + i + "'>" +
                "<div class='csc-card-label'>" + esc(c.label) + "</div>" +
                "<div class='csc-card-value'>" + c.value + "</div></div>";
    });
    html += "</div>";

    /* warranty section */
    html += section_open("Warranty", "Track warranty coverage for installed products",
        w_items.length + " items \u2192 " + w_active + " active \u2192 " + w_expiring + " expiring soon \u2192 " + w_expired + " expired");

    if (!warranty.length) {
        html += empty("No serialised products found for this customer.");
    } else {
        html += warranty_table(warranty.slice(0, LIST_LIMIT));
        html += view_all(warranty.length, "Serial No");
    }
    html += "</div>";

    /* warranty claims section */
    html += section_open("Warranty Claims", "Claims raised against installed products",
        d.claims.length + " total \u2192 " + c_open + " open \u2192 " + c_prog + " in progress \u2192 " +
        c_closed + " closed \u2192 " + c_cancelled + " cancelled");

    var claim_cards = [
        { label: "Total Claims", value: d.claims.length, key: "blue", f: { customer: customer } },
        { label: "Open", value: c_open, key: "orange", f: { customer: customer, status: "Open" } },
        { label: "In Progress", value: c_prog, key: "blue", f: { customer: customer, status: "Work In Progress" } },
        { label: "Closed", value: c_closed, key: "green", f: { customer: customer, status: "Closed" } },
        { label: "Cancelled", value: c_cancelled, key: "grey", f: { customer: customer, status: "Cancelled" } }
    ];

    html += "<div class='csc-cards csc-cards-inset'>";
    claim_cards.forEach(function (c, i) {
        html += "<div class='csc-card csc-c-" + c.key + "' data-claimcard='" + i + "'>" +
                "<div class='csc-card-label'>" + esc(c.label) + "</div>" +
                "<div class='csc-card-value'>" + c.value + "</div></div>";
    });
    html += "</div>";

    if (!d.claims.length) {
        html += empty("No warranty claims found for this customer.");
    } else {
        html += claims_table(d.claims.slice(0, LIST_LIMIT));
        html += view_all(d.claims.length, "Warranty Claim");
    }
    html += "</div>";

    /* maintenance section */
    html += section_open("Maintenance", "Planned maintenance from Maintenance Schedules",
        d.schedules.length + " schedules \u2192 " + m_completed + " completed \u2192 " + m_pending + " pending \u2192 " + m_overdue + " overdue");

    if (next_visit) {
        var nd = days_between(next_visit.r.scheduled_date, today);
        html += "<div class='csc-next' data-dt='Maintenance Schedule' data-dn='" + esc(next_visit.r.parent) + "'>" +
            "<div class='csc-next-label'>Next Maintenance</div>" +
            "<div class='csc-next-date'>" + fdate(next_visit.r.scheduled_date) + "</div>" +
            "<div class='csc-next-meta'>" + (nd === 0 ? "Today" : "In " + nd + " days") +
            " \u00b7 " + esc(next_visit.r.item_name || next_visit.r.item_code || "\u2014") +
            (next_visit.r.serial_no ? " \u00b7 " + esc(next_visit.r.serial_no) : "") +
            (next_visit.r.sales_person ? " \u00b7 " + esc(next_visit.r.sales_person) : "") + "</div></div>";
    }

    if (!details.length) {
        html += empty("No maintenance schedules found for this customer.");
    } else {
        html += schedule_table(details.slice(0, LIST_LIMIT));
        html += view_all(details.length, "Maintenance Schedule");
    }
    html += "</div>";

    /* visits section */
    var pmap = {};
    d.purposes.forEach(function (p) { if (!pmap[p.parent]) { pmap[p.parent] = p; } });

    html += section_open("Maintenance Visits", "Visits recorded against this customer",
        d.visits.length + " total \u2192 " + v_by("scheduled") + " scheduled \u2192 " + v_by("completed") +
        " completed \u2192 " + v_by("pending") + " pending \u2192 " + v_by("overdue") + " overdue");

    if (!visits.length) {
        html += empty("No maintenance visits recorded for this customer.");
    } else {
        html += visit_table(visits.slice(0, LIST_LIMIT), pmap);
        html += view_all(visits.length, "Maintenance Visit");
    }
    html += "</div>";

    /* issues section */
    html += section_open("Issues & Support", "Support tickets raised by this customer",
        d.issues.length + " total \u2192 " + i_open + " open \u2192 " + i_prog + " replied \u2192 " +
        i_res + " resolved \u2192 " + i_closed + " closed");

    if (!d.issues.length) {
        html += empty("No support issues found for this customer.");
    } else {
        html += issue_table(d.issues.slice(0, LIST_LIMIT));
        html += view_all(d.issues.length, "Issue");
    }
    html += "</div>";

    /* service history */
    var history = [];
    visits.forEach(function (x) {
        history.push({ date: x.v.mntc_date || x.v.modified, type: "Maintenance Visit",
            dt: "Maintenance Visit", dn: x.v.name, status: x.st.label, key: x.st.key });
    });
    d.claims.forEach(function (c) {
        history.push({ date: c.complaint_date || c.modified, type: "Warranty Claim",
            dt: "Warranty Claim", dn: c.name, status: c.status,
            key: claim_bucket(c.status) === "closed" ? "completed" : "pending" });
    });
    d.issues.forEach(function (i) {
        history.push({ date: i.opening_date || i.modified, type: "Issue",
            dt: "Issue", dn: i.name, status: i.status,
            key: issue_bucket(i.status) === "open" ? "pending" : "completed" });
    });
    d.installs.forEach(function (i) {
        history.push({ date: i.scheduled_date || i.modified, type: "Installation",
            dt: "Installation", dn: i.name, status: i.installation_status,
            key: i.installation_status === "Completed" ? "completed" : "pending" });
    });
    d.commissions.forEach(function (c) {
        history.push({ date: c.modified, type: "Project Commission",
            dt: "Project Commission", dn: c.name, status: c.status_of_project_commission,
            key: String(c.status_of_project_commission || "").toLowerCase() === "commissioned" ? "completed" : "pending" });
    });
    history = history.filter(function (h) { return h.date; })
        .sort(function (a, b) { return String(b.date).localeCompare(String(a.date)); });
    var history_total = history.length;

    html += "<div id='csc-history-anchor'></div>";
    html += section_open("Recent Service History", "Combined post-installation activity",
        history_total + " activities");
    if (!history.length) {
        html += empty("No service activity recorded yet.");
    } else {
        html += timeline(history.slice(0, LIST_LIMIT));
    }
    html += "</div>";

    /* reports */
    var reports = [
        { icon: "\ud83d\udee1", title: "Warranty Report", sub: "Coverage and expiry by product",
          stats: [[w_items.length, "Items"], [w_active, "Active"], [w_expiring, "Expiring"], [w_expired, "Expired"]],
          dt: "Serial No", f: { custom_customer: customer } },
        { icon: "\ud83d\udcdc", title: "Warranty Claims Report", sub: "Claims raised and their state",
          stats: [[d.claims.length, "Claims"], [c_open, "Open"], [c_prog, "In Progress"], [c_closed, "Closed"]],
          dt: "Warranty Claim", f: { customer: customer } },
        { icon: "\ud83d\uddd3", title: "Maintenance Report", sub: "Planned maintenance schedules",
          stats: [[d.schedules.length, "Schedules"], [m_completed, "Completed"], [m_pending, "Pending"], [m_overdue, "Overdue"]],
          dt: "Maintenance Schedule", f: { customer: customer } },
        { icon: "\ud83d\udd27", title: "Maintenance Visits Report", sub: "Visits carried out on site",
          stats: [[d.visits.length, "Visits"], [v_by("completed"), "Completed"], [v_by("pending"), "Pending"], [v_by("overdue"), "Overdue"]],
          dt: "Maintenance Visit", f: { customer: customer } },
        { icon: "\ud83d\udcac", title: "Issues & Support Report", sub: "Tickets raised by this customer",
          stats: [[d.issues.length, "Issues"], [i_open, "Open"], [i_prog, "Replied"], [i_res, "Resolved"]],
          dt: "Issue", f: { customer: customer } },
        { icon: "\ud83d\udce6", title: "Installed Products Report", sub: "Serialised products on site",
          stats: [[d.serials.length, "Products"], [w_items.length, "Under Warranty"]],
          dt: "Serial No", f: { custom_customer: customer } },
        { icon: "\ud83d\udd52", title: "Service History Report", sub: "All post-installation activity",
          stats: [[history_total, "Activities"]], scroll: true }
    ];

    html += section_open("Reports", "Customer-specific summaries. Every report opens filtered to " + esc(customer) + ".", "");
    html += "<div class='csc-reports'>";
    reports.forEach(function (r, i) {
        html += "<div class='csc-report' data-rep='" + i + "'>" +
            "<div class='csc-rep-head'><span class='csc-rep-icon'>" + r.icon + "</span>" +
            "<div><div class='csc-rep-title'>" + esc(r.title) + "</div>" +
            "<div class='csc-rep-sub'>" + esc(r.sub) + "</div></div></div>" +
            "<div class='csc-rep-stats'>";
        r.stats.forEach(function (s) {
            html += "<div class='csc-rep-stat'><b>" + s[0] + "</b><span>" + esc(s[1]) + "</span></div>";
        });
        html += "</div><button class='csc-btn csc-rep-btn'>" +
            (r.scroll ? "View Details" : "View Report") + "</button></div>";
    });
    html += "</div></div>";

    /* ---------- embedded report data ---------- */

    html += section_open("Embedded Reports", "Live report data for " + esc(customer) + ", without leaving this page", "");
    html += "<div class='csc-embed'>";

    html += panel("Warranty Items Report", "Warranty coverage per serialised product", true,
        chips([[w_items.length, "Items", "blue"], [w_active, "Active", "green"],
               [w_expiring, "Expiring Soon", "orange"], [w_expired, "Expired", "red"]]) +
        (warranty.length ? warranty_table(warranty.slice(0, LIST_LIMIT)) + view_all(warranty.length, "Serial No")
                         : empty("No warranty items found for this customer.")));

    var ledger_body;
    if (!d.ledger.length) {
        ledger_body = empty("No serial number transactions found for this customer.");
    } else {
        ledger_body = "<div class='csc-scroll'><table class='csc-table'><thead><tr>" +
            "<th>Date</th><th>Item</th><th>Serial No</th><th>Transaction</th>" +
            "<th>Reference</th><th>Warehouse</th><th>Qty</th></tr></thead><tbody>";
        d.ledger.slice(0, LEDGER_LIMIT).forEach(function (l) {
            ledger_body += "<tr>" +
                "<td>" + fdate(l.date) + "</td>" +
                "<td>" + (l.item_code ? "<a class='csc-link' data-dt='Item' data-dn='" + esc(l.item_code) + "'>" + esc(l.item_name || l.item_code) + "</a>" : "\u2014") + "</td>" +
                "<td><a class='csc-link' data-dt='Serial No' data-dn='" + esc(l.serial_no) + "'>" + esc(l.serial_no) + "</a></td>" +
                "<td><span class='csc-pill csc-p-" + (l.type === "Inward" ? "active" : "scheduled") + "'>" + esc(l.type || "\u2014") + "</span></td>" +
                "<td>" + (l.voucher_no ? "<a class='csc-link' data-dt='" + esc(l.voucher_type) + "' data-dn='" + esc(l.voucher_no) + "'>" + esc(l.voucher_no) + "</a>" : "\u2014") + "</td>" +
                "<td>" + esc(l.warehouse || "\u2014") + "</td>" +
                "<td>" + (l.qty !== undefined && l.qty !== null ? l.qty : "\u2014") + "</td>" +
                "</tr>";
        });
        ledger_body += "</tbody></table></div>";
        if (d.ledger.length > LEDGER_LIMIT) {
            ledger_body += "<div class='csc-foot-note'>Showing the latest " + LEDGER_LIMIT +
                " of " + d.ledger.length + " movements. The standard Serial No Ledger report " +
                "runs one serial at a time, so open a Serial No above to see its full ledger.</div>";
        }
    }
    html += panel("Serial Number Ledger", "Stock movements for this customer's serials", true,
        chips([[d.ledger.length, "Movements", "blue"], [d.serials.length, "Serials", "green"]]) + ledger_body);

    var expiry_rows = w_items.slice().sort(function (a, b) {
        return String(a.s.warranty_expiry_date).localeCompare(String(b.s.warranty_expiry_date));
    });
    html += panel("Serial No Warranty Expiry", "Serials ordered by soonest expiry", false,
        chips([[w_active, "Active", "green"], [w_expiring, "Expiring Soon", "orange"], [w_expired, "Expired", "red"]]) +
        (expiry_rows.length ? warranty_table(expiry_rows.slice(0, LIST_LIMIT)) + view_all(expiry_rows.length, "Serial No")
                            : empty("No serials with a warranty expiry date for this customer.")));

    html += panel("Warranty Claims Report", "Claims and their current state", false,
        chips([[d.claims.length, "Total", "blue"], [c_open, "Open", "orange"],
               [c_prog, "In Progress", "blue"], [c_closed, "Closed", "green"],
               [c_cancelled, "Cancelled", "grey"]]) +
        (d.claims.length ? claims_table(d.claims.slice(0, LIST_LIMIT)) + view_all(d.claims.length, "Warranty Claim")
                         : empty("No warranty claims found for this customer.")));

    html += panel("Maintenance Report", "Planned maintenance rows from Maintenance Schedules", false,
        chips([[details.length, "Planned", "blue"], [m_completed, "Completed", "green"],
               [m_pending, "Pending", "orange"], [m_upcoming, "Upcoming", "blue"],
               [m_overdue, "Overdue", "red"]]) +
        (details.length ? schedule_table(details.slice(0, LIST_LIMIT)) + view_all(details.length, "Maintenance Schedule")
                        : empty("No maintenance schedules found for this customer.")));

    html += panel("Maintenance Visits Report", "Visits carried out on site", false,
        chips([[d.visits.length, "Total", "blue"], [v_by("scheduled"), "Scheduled", "blue"],
               [v_by("completed"), "Completed", "green"], [v_by("pending"), "Pending", "orange"],
               [v_by("cancelled"), "Cancelled", "grey"], [v_by("overdue"), "Overdue", "red"]]) +
        (visits.length ? visit_table(visits.slice(0, LIST_LIMIT), pmap) + view_all(visits.length, "Maintenance Visit")
                       : empty("No maintenance visits found for this customer.")));

    html += panel("Issue Summary", "Support tickets by status", false,
        chips([[d.issues.length, "Total", "blue"], [i_open, "Open", "orange"],
               [i_prog, "Replied", "blue"], [i_res, "Resolved", "green"],
               [i_closed, "Closed", "grey"]]) +
        (d.issues.length ? issue_table(d.issues.slice(0, LIST_LIMIT)) + view_all(d.issues.length, "Issue")
                         : empty("No support issues found for this customer.")));

    var frt_body;
    if (!d.issues.length) {
        frt_body = empty("First Response Time data is not available for this customer.");
    } else if (!responded.length) {
        frt_body = empty("No issue for this customer has been responded to yet.");
    } else {
        frt_body = "<div class='csc-scroll'><table class='csc-table'><thead><tr>" +
            "<th>Issue</th><th>Subject</th><th>Opened</th><th>First Responded</th>" +
            "<th>Response Time</th><th>SLA</th><th>Status</th><th>Assigned</th></tr></thead><tbody>";
        responded.slice(0, LIST_LIMIT).forEach(function (i) {
            frt_body += "<tr>" +
                "<td><a class='csc-link' data-dt='Issue' data-dn='" + esc(i.name) + "'>" + esc(i.name) + "</a></td>" +
                "<td class='csc-subject'>" + esc(i.subject || "\u2014") + "</td>" +
                "<td>" + fdate(i.opening_date) + "</td>" +
                "<td>" + fdate(i.first_responded_on) + "</td>" +
                "<td>" + dur(i.first_response_time) + "</td>" +
                "<td>" + esc(i.agreement_status || "\u2014") + "</td>" +
                "<td><span class='csc-pill csc-i-" + issue_bucket(i.status) + "'>" + esc(i.status) + "</span></td>" +
                "<td>" + esc(assignee(i._assign)) + "</td>" +
                "</tr>";
        });
        frt_body += "</tbody></table></div>" + view_all(responded.length, "Issue");
    }
    html += panel("First Response Time", "How quickly this customer's issues were first answered", false,
        chips([[responded.length, "Responded", "green"],
               [d.issues.length - responded.length, "Awaiting Response", "orange"],
               [avg_first ? dur(avg_first) : "\u2014", "Average", "blue"]]) + frt_body);

    html += panel("Service History", "Every post-installation activity, newest first", false,
        chips([[history_total, "Activities", "blue"]]) +
        (history.length ? timeline(history.slice(0, LEDGER_LIMIT))
                        : empty("No service activity recorded yet.")));

    html += "</div></div>";
    html += "</div>";

    field.$wrapper.html(html);

    /* ---- bindings ---- */
    var $w = field.$wrapper;

    $w.find(".csc-refresh").on("click", function () { csc_load(frm); });

    $w.find(".csc-card[data-card]").on("click", function () {
        var c = cards[parseInt($(this).attr("data-card"), 10)];
        if (c) { frappe.set_route("List", c.dt, c.f); }
    });

    $w.find(".csc-card[data-claimcard]").on("click", function () {
        var c = claim_cards[parseInt($(this).attr("data-claimcard"), 10)];
        if (c) { frappe.set_route("List", "Warranty Claim", c.f); }
    });

    $w.find(".csc-report").on("click", function () {
        var r = reports[parseInt($(this).attr("data-rep"), 10)];
        if (!r) { return; }
        if (r.scroll) {
            var anchor = $w.find("#csc-history-anchor").get(0);
            if (anchor && anchor.scrollIntoView) { anchor.scrollIntoView({ behavior: "smooth", block: "start" }); }
            return;
        }
        frappe.set_route("List", r.dt, r.f);
    });

    $w.find(".csc-link, .csc-next[data-dn], .csc-view-all").on("click", function (e) {
        e.stopPropagation();
        var dt = $(this).attr("data-dt");
        var dn = $(this).attr("data-dn");
        if (dt && dn) { frappe.set_route("Form", dt, dn); return; }
        if (dt) { frappe.set_route("List", dt, csc_list_filter(dt, customer)); }
    });
}

/* ---------- shared table builders -------------------------------------- */

function warranty_table(rows) {
    var h = "<div class='csc-scroll'><table class='csc-table'><thead><tr>" +
        "<th>Product</th><th>Serial No</th><th>Installed</th><th>Warranty Expiry</th>" +
        "<th>Status</th><th>Days Left</th><th>AMC</th></tr></thead><tbody>";
    rows.forEach(function (r) {
        h += "<tr>" +
            "<td><a class='csc-link' data-dt='Item' data-dn='" + esc(r.s.item_code) + "'>" + esc(r.s.item_name || r.s.item_code) + "</a></td>" +
            "<td><a class='csc-link' data-dt='Serial No' data-dn='" + esc(r.s.name) + "'>" + esc(r.s.name) + "</a></td>" +
            "<td>" + fdate(r.s.custom_consumed_date) + "</td>" +
            "<td>" + fdate(r.s.warranty_expiry_date) + "</td>" +
            "<td><span class='csc-pill csc-p-" + r.w.key + "'>" + esc(r.w.label) + "</span></td>" +
            "<td>" + days_text(r.w) + "</td>" +
            "<td><span class='csc-pill csc-p-" + r.a.key + "'>" + esc(r.a.key === "none" ? "No AMC" : r.a.label) + "</span></td>" +
            "</tr>";
    });
    return h + "</tbody></table></div>";
}

function claims_table(rows) {
    var h = "<div class='csc-scroll'><table class='csc-table'><thead><tr>" +
        "<th>Claim</th><th>Product</th><th>Serial No</th><th>Claim Date</th>" +
        "<th>Warranty / AMC</th><th>Status</th><th>Assigned To</th><th>Updated</th></tr></thead><tbody>";
    rows.forEach(function (c) {
        h += "<tr>" +
            "<td><a class='csc-link' data-dt='Warranty Claim' data-dn='" + esc(c.name) + "'>" + esc(c.name) + "</a></td>" +
            "<td>" + (c.item_code ? "<a class='csc-link' data-dt='Item' data-dn='" + esc(c.item_code) + "'>" + esc(c.item_name || c.item_code) + "</a>" : "\u2014") + "</td>" +
            "<td>" + (c.serial_no ? "<a class='csc-link' data-dt='Serial No' data-dn='" + esc(c.serial_no) + "'>" + esc(c.serial_no) + "</a>" : "\u2014") + "</td>" +
            "<td>" + fdate(c.complaint_date) + "</td>" +
            "<td>" + esc(c.warranty_amc_status || "\u2014") + "</td>" +
            "<td><span class='csc-pill csc-cl-" + claim_bucket(c.status) + "'>" + esc(c.status || "\u2014") + "</span></td>" +
            "<td>" + esc(assignee(c._assign, c.resolved_by)) + "</td>" +
            "<td>" + fdate(c.modified) + "</td>" +
            "</tr>";
    });
    return h + "</tbody></table></div>";
}

function schedule_table(rows) {
    var h = "<div class='csc-scroll'><table class='csc-table'><thead><tr>" +
        "<th>Schedule</th><th>Product</th><th>Serial No</th><th>Scheduled</th>" +
        "<th>Actual</th><th>Assigned</th><th>Status</th></tr></thead><tbody>";
    rows.forEach(function (x) {
        h += "<tr>" +
            "<td><a class='csc-link' data-dt='Maintenance Schedule' data-dn='" + esc(x.r.parent) + "'>" + esc(x.r.parent) + "</a></td>" +
            "<td><a class='csc-link' data-dt='Item' data-dn='" + esc(x.r.item_code) + "'>" + esc(x.r.item_name || x.r.item_code) + "</a></td>" +
            "<td>" + (x.r.serial_no ? esc(x.r.serial_no) : "\u2014") + "</td>" +
            "<td>" + fdate(x.r.scheduled_date) + "</td>" +
            "<td>" + fdate(x.r.actual_date) + "</td>" +
            "<td>" + (x.r.sales_person ? esc(x.r.sales_person) : "\u2014") + "</td>" +
            "<td><span class='csc-pill csc-p-" + x.st.key + "'>" + esc(x.st.label) + "</span></td>" +
            "</tr>";
    });
    return h + "</tbody></table></div>";
}

function visit_table(rows, pmap) {
    var h = "<div class='csc-scroll'><table class='csc-table'><thead><tr>" +
        "<th>Visit</th><th>Product</th><th>Serial No</th><th>Type</th>" +
        "<th>Date</th><th>Technician</th><th>Status</th></tr></thead><tbody>";
    rows.forEach(function (x) {
        var p = pmap[x.v.name] || {};
        h += "<tr>" +
            "<td><a class='csc-link' data-dt='Maintenance Visit' data-dn='" + esc(x.v.name) + "'>" + esc(x.v.name) + "</a></td>" +
            "<td>" + (p.item_code ? "<a class='csc-link' data-dt='Item' data-dn='" + esc(p.item_code) + "'>" + esc(p.item_name || p.item_code) + "</a>" : "\u2014") + "</td>" +
            "<td>" + (p.serial_no ? esc(p.serial_no) : "\u2014") + "</td>" +
            "<td>" + esc(x.v.maintenance_type || "\u2014") + "</td>" +
            "<td>" + fdate(x.v.mntc_date) + "</td>" +
            "<td>" + (p.service_person ? esc(p.service_person) : "\u2014") + "</td>" +
            "<td><span class='csc-pill csc-p-" + x.st.key + "'>" + esc(x.st.label) + "</span></td>" +
            "</tr>";
    });
    return h + "</tbody></table></div>";
}

function issue_table(rows) {
    var h = "<div class='csc-scroll'><table class='csc-table'><thead><tr>" +
        "<th>Issue</th><th>Subject</th><th>Priority</th><th>Status</th>" +
        "<th>Opened</th><th>Updated</th><th>Assigned</th></tr></thead><tbody>";
    rows.forEach(function (i) {
        h += "<tr>" +
            "<td><a class='csc-link' data-dt='Issue' data-dn='" + esc(i.name) + "'>" + esc(i.name) + "</a></td>" +
            "<td class='csc-subject'>" + esc(i.subject || "\u2014") + "</td>" +
            "<td><span class='csc-pill csc-pr-" + priority_key(i.priority) + "'>" + esc(i.priority || "\u2014") + "</span></td>" +
            "<td><span class='csc-pill csc-i-" + issue_bucket(i.status) + "'>" + esc(i.status) + "</span></td>" +
            "<td>" + fdate(i.opening_date) + "</td>" +
            "<td>" + fdate(i.modified) + "</td>" +
            "<td>" + esc(assignee(i._assign)) + "</td>" +
            "</tr>";
    });
    return h + "</tbody></table></div>";
}

function timeline(rows) {
    var h = "<div class='csc-timeline'>";
    rows.forEach(function (x) {
        h += "<div class='csc-tl-row csc-link' data-dt='" + esc(x.dt) + "' data-dn='" + esc(x.dn) + "'>" +
            "<span class='csc-dot csc-dot-" + (x.key === "completed" ? "green" : "orange") + "'></span>" +
            "<span class='csc-tl-date'>" + fdate(x.date) + "</span>" +
            "<span class='csc-tl-type'>" + esc(x.type) + "</span>" +
            "<span class='csc-tl-rec'>" + esc(x.dn) + "</span>" +
            "<span class='csc-tl-status'>" + esc(x.status || "\u2014") + "</span></div>";
    });
    return h + "</div>";
}

/* ---------- small builders --------------------------------------------- */

// Native details/summary - collapse works with no JS, so it cannot break.
function panel(title, sub, is_open, body) {
    return "<details class='csc-panel'" + (is_open ? " open" : "") + ">" +
        "<summary class='csc-panel-head'><span class='csc-caret'>\u25b8</span>" +
        "<span class='csc-panel-title'>" + esc(title) + "</span>" +
        "<span class='csc-panel-sub'>" + esc(sub) + "</span></summary>" +
        "<div class='csc-panel-body'>" + body + "</div></details>";
}

function chips(list) {
    var h = "<div class='csc-chips'>";
    list.forEach(function (c) {
        h += "<div class='csc-chip csc-c-" + c[2] + "'><b>" + esc(c[0]) + "</b><span>" + esc(c[1]) + "</span></div>";
    });
    return h + "</div>";
}

// Serial No is linked through the custom field, everything else through customer.
function csc_list_filter(dt, customer) {
    if (dt === "Serial No") { return { custom_customer: customer }; }
    if (dt === "Item") { return {}; }
    return { customer: customer };
}

function section_open(title, subtitle, summary) {
    return "<div class='csc-section'><div class='csc-sec-head'>" +
        "<div><div class='csc-sec-title'>" + esc(title) + "</div>" +
        "<div class='csc-sec-sub'>" + esc(subtitle) + "</div></div>" +
        (summary ? "<div class='csc-sec-summary'>" + esc(summary) + "</div>" : "") +
        "</div>";
}

function view_all(total, dt) {
    if (total <= LIST_LIMIT) { return ""; }
    return "<div class='csc-viewall-wrap'><button class='csc-btn csc-view-all' data-dt='" + esc(dt) + "'>" +
        "View all " + total + "</button></div>";
}

function empty(msg) {
    return "<div class='csc-empty'><div class='csc-empty-icon'>\u25cb</div><div>" + esc(msg) + "</div></div>";
}

