// Lead: Fetch Location (GPS) -> Latitude, Longitude, Place, Address.
// Same approach as Employee Checkin on group.hipersignerp.cloud.
// Latitude/Longitude can also be typed manually; Place and Address are then looked up automatically.
(() => {
	const LAT = "custom_latitude";
	const LON = "custom_longitude";
	const PLACE = "custom_location_name";
	const ADDRESS = "custom_address";
	let timer = null;
	let last_auto_address = null;

	function has_coords(doc) {
		const lat = flt(doc[LAT]), lon = flt(doc[LON]);
		return !(Math.abs(lat) < 1e-7 && Math.abs(lon) < 1e-7);
	}

	function set_help(frm, note) {
		let html = "";
		if (has_coords(frm.doc)) {
			const la = flt(frm.doc[LAT], 7), lo = flt(frm.doc[LON], 7);
			const url = `https://www.google.com/maps?q=${la},${lo}`;
			const link = `<a href="${url}" target="_blank" rel="noopener noreferrer">${__("Open in map")} &#8599;</a>`;
			html = note ? `${frappe.utils.escape_html(note)} &middot; ${link}` : link;
		} else if (note) {
			html = frappe.utils.escape_html(note);
		}
		frm.set_df_property(PLACE, "description", html);
	}

	function lookup(frm) {
		if (!has_coords(frm.doc)) { set_help(frm, ""); return; }
		const lat = frm.doc[LAT], lon = frm.doc[LON];
		set_help(frm, __("Detecting place..."));
		frappe.call({
			method: "get_lead_place",
			args: { latitude: lat, longitude: lon },
			callback(r) {
				if (frm.doc[LAT] !== lat || frm.doc[LON] !== lon) return; // stale
				const d = r.message || {};
				if (d.place) {
					frm.set_value(PLACE, d.place);
					set_help(frm, "");
				} else {
					set_help(frm, __("Place name unavailable - you can type it"));
				}
				// Address: fill if empty, or replace if it was filled automatically before
				if (d.address && (!frm.doc[ADDRESS] || frm.doc[ADDRESS] === last_auto_address)) {
					frm.set_value(ADDRESS, d.address);
					last_auto_address = d.address;
				}
				if (d.city && !frm.doc.city) frm.set_value("city", d.city);
				if (d.state && !frm.doc.state) frm.set_value("state", d.state);
			},
			error() { set_help(frm, __("Place name unavailable - you can type it")); },
		});
	}

	function schedule(frm) {
		clearTimeout(timer);
		timer = setTimeout(() => lookup(frm), 500);
	}

	function fetch_gps(frm) {
		if (!navigator.geolocation) {
			frappe.msgprint(__("Geolocation is not supported by this browser. Please enter Latitude and Longitude manually."));
			return;
		}
		frappe.dom.freeze(__("Fetching your location..."));
		navigator.geolocation.getCurrentPosition(
			(pos) => {
				frappe.dom.unfreeze();
				const lat = flt(pos.coords.latitude, 7);
				const lon = flt(pos.coords.longitude, 7);
				frm.doc[LAT] = lat; // set both first so only one lookup runs
				frm.set_value(LON, lon);
				frm.set_value(LAT, lat);
				frappe.show_alert({
					message: __("Location captured (accuracy about {0} m)", [Math.round(pos.coords.accuracy || 0)]),
					indicator: "green",
				});
				schedule(frm);
			},
			(err) => {
				frappe.dom.unfreeze();
				let msg = __("Unable to fetch location.");
				if (err && err.code === 1) msg = __("Location permission was denied. Please allow location access in your browser, or enter Latitude and Longitude manually.");
				else if (err && err.code === 3) msg = __("Location request timed out. Please try again, or enter Latitude and Longitude manually.");
				frappe.msgprint({ title: __("Fetch Location"), message: msg, indicator: "orange" });
			},
			{ enableHighAccuracy: true, timeout: 20000, maximumAge: 0 }
		);
	}

	frappe.ui.form.on("Lead", {
		refresh(frm) {
			last_auto_address = null;
			if (has_coords(frm.doc) && !frm.doc[PLACE]) {
				schedule(frm);
			} else {
				set_help(frm, "");
			}
		},
		custom_fetch_location(frm) { fetch_gps(frm); },
		custom_latitude(frm) { schedule(frm); },
		custom_longitude(frm) { schedule(frm); },
	});
})();

// Paper Work: auto-fetch MNRE details + Location from the Lead.
// Lead is found from: Lead field -> Customer (Customer.lead_name).
(() => {
	const DT = "Paper Work";
	const LEAD_FIELD = "custom_lead";
	const MAP = {
		custom_consumer_no: "custom_consumer_no",
		custom_kseb_phone_number: "custom_kseb_phone_number",
		custom_email: "email_id",
		custom_address: (d) => d.custom_address || [d.city, d.state].filter(Boolean).join(", "),
		custom_current_bill: "custom_current_bill",
		custom_current_bill_image: "custom_current_bill_image",
		custom_latitude: "custom_latitude",
		custom_longitude: "custom_longitude",
		custom_location_name: "custom_location_name",
	};

	function map_link(frm) {
		const la = flt(frm.doc.custom_latitude, 7), lo = flt(frm.doc.custom_longitude, 7);
		const html = (Math.abs(la) > 1e-7 || Math.abs(lo) > 1e-7)
			? `<a href="https://www.google.com/maps?q=${la},${lo}" target="_blank" rel="noopener noreferrer">${__("Open in map")} &#8599;</a>`
			: "";
		frm.set_df_property("custom_location_name", "description", html);
	}

	function apply(frm, d, overwrite) {
		if (!d || !d.lead) return;
		if (LEAD_FIELD && frm.doc[LEAD_FIELD] !== d.lead) {
			frm.__skip_lead_trigger = true;
			frm.set_value(LEAD_FIELD, d.lead);
		}
		let n = 0;
		Object.keys(MAP).forEach((t) => {
			if (!frm.fields_dict[t]) return;
			const src = MAP[t];
			const v = typeof src === "function" ? src(d) : d[src];
			if (v === undefined || v === null || v === "") return;
			if (!overwrite && frm.doc[t]) return;
			if (frm.doc[t] === v) return;
			frm.set_value(t, v);
			n++;
		});
		if (n) frappe.show_alert({ message: __("{0} field(s) fetched from Lead {1}", [n, d.lead]), indicator: "blue" });
		setTimeout(() => map_link(frm), 300);
	}

	function pull(frm, overwrite, args) {
		args = args || { lead: frm.doc[LEAD_FIELD], customer: frm.doc.customer };
		if (!args.lead && !args.customer && !args.quotation) return;
		frappe.call({
			method: "get_lead_details",
			args: args,
			callback(r) {
				const d = r.message || {};
				if (!d.lead && overwrite === "manual") {
					frappe.msgprint(__("No Lead is linked. Set the Lead field, or set 'From Lead' on the Customer."));
				}
				apply(frm, d, !!overwrite);
			},
		});
	}

	frappe.ui.form.on(DT, {
		refresh(frm) {
			map_link(frm);
			if (frm.is_new()) {
				pull(frm, false);
			} else if (frm.doc.docstatus === 0) {
				frm.add_custom_button(__("Fetch from Lead"), () => pull(frm, "manual"));
			}
		},
		customer(frm) {
			if (frm.doc.customer) pull(frm, true, { customer: frm.doc.customer });
		},
		custom_lead(frm) {
			if (frm.__skip_lead_trigger) { frm.__skip_lead_trigger = false; return; }
			if (frm.doc.custom_lead) pull(frm, true, { lead: frm.doc.custom_lead });
		},
		custom_latitude(frm) { map_link(frm); },
		custom_longitude(frm) { map_link(frm); },
	});
})();

// Site Visit: Lead / Customer linking + auto-fetch from the Lead.
// Works from a Lead (no Customer yet) or from a Customer. Fills Employee from the
// Lead's Assigned Employee, and picks up the Customer once the Lead is converted.
(() => {
	const DT = "Site Visit";
	const MAP = {
		employee: "employee",
		company: "company",
		contact_person: "lead_name",
		phone: (d) => d.mobile_no || d.phone,
		location_site_address: (d) => d.custom_address || [d.city, d.state].filter(Boolean).join(", "),
		custom_latitude: "custom_latitude",
		custom_longitude: "custom_longitude",
		custom_location_name: "custom_location_name",
	};

	function map_link(frm) {
		if (!frm.fields_dict.custom_location_name) return;
		const la = flt(frm.doc.custom_latitude, 7), lo = flt(frm.doc.custom_longitude, 7);
		const html = (Math.abs(la) > 1e-7 || Math.abs(lo) > 1e-7)
			? `<a href="https://www.google.com/maps?q=${la},${lo}" target="_blank" rel="noopener noreferrer">${__("Open in map")} &#8599;</a>` : "";
		frm.set_df_property("custom_location_name", "description", html);
	}

	function apply(frm, d, overwrite) {
		if (!d || !d.lead) return;
		const sets = [];
		frm.__lead_applying = true;
		// link fields: Lead always; Customer only when the Lead has been converted
		if (frm.doc.custom_lead !== d.lead) sets.push(frm.set_value("custom_lead", d.lead));
		if (d.customer && !frm.doc.customer) sets.push(frm.set_value("customer", d.customer));
		let n = 0;
		Object.keys(MAP).forEach((t) => {
			if (!frm.fields_dict[t]) return;
			const src = MAP[t];
			const v = typeof src === "function" ? src(d) : d[src];
			if (v === undefined || v === null || v === "") return;
			if (!overwrite && frm.doc[t]) return;
			if (frm.doc[t] === v) return;
			sets.push(frm.set_value(t, v));
			n++;
		});
		Promise.all(sets).finally(() => { frm.__lead_applying = false; map_link(frm); });
		if (n) frappe.show_alert({ message: __("{0} field(s) fetched from Lead {1}", [n, d.lead]), indicator: "blue" });
	}

	function pull(frm, mode, args) {
		args = args || { lead: frm.doc.custom_lead, customer: frm.doc.customer, quotation: frm.doc.quotation };
		if (!args.lead && !args.customer && !args.quotation) return;
		frappe.call({
			method: "get_lead_details",
			args: args,
			callback(r) {
				const d = r.message || {};
				if (!d.lead && mode === "manual") frappe.msgprint(__("No Lead found. Set the Lead field, or 'From Lead' on the Customer."));
				apply(frm, d, !!mode);
			},
		});
	}

	function on_link(field) {
		return (frm) => {
			if (frm.__lead_applying || !frm.doc[field]) return;
			const a = {};
			a[field === "custom_lead" ? "lead" : field] = frm.doc[field];
			pull(frm, true, a);
		};
	}

	frappe.ui.form.on(DT, {
		refresh(frm) {
			map_link(frm);
			if (frm.is_new()) {
				pull(frm, false);
			} else if (frm.doc.docstatus === 0) {
				frm.add_custom_button(__("Fetch from Lead"), () => pull(frm, "manual"));
				if (frm.doc.custom_lead && !frm.doc.customer) {
					frm.dashboard.set_headline(__("Started from Lead {0}. The Customer will be filled in automatically when this Lead is converted to a Customer.", [frm.doc.custom_lead.bold()]));
				}
			}
		},
		custom_lead: on_link("custom_lead"),
		customer: on_link("customer"),
		quotation: on_link("quotation"),
		custom_latitude(frm) { map_link(frm); },
		custom_longitude(frm) { map_link(frm); },
	});
})();

