(function () {

/* =========================================================================
   LEAD WORK STAGE (same as greenvalley.hipersignerp.cloud)
   Lead -> Loan -> Site Visit -> Quotation -> Convert to Customer
   ========================================================================= */

const LWS_STAGES = [
    { key: "lead", no: 1, title: "Lead", doctype: "Lead", icon: "\ud83d\udc64", done_statuses: ["Converted"] },
    { key: "loan", no: 2, title: "Loan", doctype: "Solar Loan", icon: "\ud83c\udfe6", optional: true, done_statuses: ["Approved"] },
    { key: "site_visit", no: 3, title: "Site Visit", doctype: "Site Visit", icon: "\ud83d\udccd", assigned_field: "employee", done_statuses: ["Approved"] },
    { key: "quotation", no: 4, title: "Quotation", doctype: "Quotation", icon: "\ud83d\udcdd", done_statuses: ["Ordered", "Partially Ordered"] },
    { key: "customer", no: 5, title: "Convert to Customer", doctype: "Customer", icon: "\ud83e\udd1d", done_statuses: ["Converted"] }
];

frappe.ui.form.on("Lead", {
    refresh(frm) {
        if (frm.is_new()) return;
        setTimeout(() => lws_load(frm), 300);
    }
});

/* ------------------------------- FETCH ------------------------------- */

async function lws_list(doctype, filters, extra_fields, or_filters) {
    try {
        const args = {
            fields: ["name", "creation", "modified", "owner"].concat(extra_fields || []),
            order_by: "creation desc",
            limit: 50
        };
        if (filters) args.filters = filters;
        if (or_filters) args.or_filters = or_filters;
        return (await frappe.db.get_list(doctype, args)) || [];
    } catch (e) {
        console.log("Lead Work Stage: could not load " + doctype, e);
        return [];
    }
}

async function lws_load(frm) {
    const field = frm.fields_dict["custom_lead_work_stage"];
    if (!field) return;
    const lead = frm.doc.name;

    const [loans, visits, quotes, customers] = await Promise.all([
        lws_list("Solar Loan", { custom_lead: lead }, ["status", "customer"]),
        lws_list("Site Visit", { custom_lead: lead }, ["status", "employee", "customer"]),
        lws_list("Quotation", { docstatus: ["<", 2] }, ["status", "docstatus"], { custom_lead: lead, party_name: lead }),
        lws_list("Customer", { lead_name: lead }, ["customer_name"])
    ]);

    quotes.forEach(q => { if (q.docstatus === 0) q.status = "Draft"; });
    visits.forEach(v => { v.assigned_to = v.employee || ""; });
    customers.forEach(c => { c.status = "Converted"; });

    const records = { loan: loans, site_visit: visits, quotation: quotes, customer: customers };

    const stage_data = {
        lead: { exists: true, name: lead, status: frm.doc.status, creation: frm.doc.creation, modified: frm.doc.modified, owner: frm.doc.owner, count: 1, assigned_to: frm.doc.custom_assigned_employee || "" }
    };
    Object.keys(records).forEach(k => {
        const list = records[k];
        stage_data[k] = list.length ? Object.assign({ exists: true, count: list.length }, list[0]) : { exists: false, count: 0 };
    });

    // Current stage: Customer once converted, otherwise the most recently updated record
    let current_stage = LWS_STAGES[0];
    if (stage_data.customer.exists) {
        current_stage = LWS_STAGES[4];
    } else {
        let latest = null;
        ["loan", "site_visit", "quotation"].forEach(k => {
            const d = stage_data[k];
            if (d.exists && (!latest || new Date(d.modified) > latest)) {
                latest = new Date(d.modified);
                current_stage = LWS_STAGES.find(s => s.key === k);
            }
        });
    }

    lws_render(frm, field, stage_data, records, current_stage);
}

/* ------------------------------- HELPERS ------------------------------- */

function lws_cat(stage, data) {
    if (!data || !data.exists) return "none";
    const raw = (data.status || "").toString().trim().toLowerCase();
    return (stage.done_statuses || []).map(s => s.toLowerCase()).includes(raw) ? "green" : "blue";
}
function lws_status(s) {
    if (!s || String(s).trim() === "") return "Pending";
    const map = { "processing": "Processing", "On hold": "On Hold" };
    return map[String(s).trim()] || String(s).trim();
}
function lws_dt(v) {
    if (!v) return "\u2014";
    try { return frappe.datetime.str_to_user(v); } catch (e) { return v; }
}
function lws_esc(v) {
    if (v === null || v === undefined) return "";
    return String(v).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#039;");
}

/* ------------------------------- CREATE ------------------------------- */

function lws_address(d) {
    return d.custom_address || [d.city, d.state].filter(Boolean).join(", ");
}

function lws_create(frm, key, customer) {
    const d = frm.doc;
    if (key === "loan") {
        const v = { custom_lead: d.name, customer_name: d.lead_name, contact_no: d.mobile_no || d.phone, email: d.email_id, address: lws_address(d) };
        if (d.company) v.company = d.company;
        if (customer) v.customer = customer;
        frappe.new_doc("Solar Loan", v);
    } else if (key === "site_visit") {
        const v = {
            custom_lead: d.name, custom_lead_name: d.lead_name, contact_person: d.lead_name, phone: d.mobile_no || d.phone,
            location_site_address: lws_address(d), custom_latitude: d.custom_latitude, custom_longitude: d.custom_longitude,
            custom_location_name: d.custom_location_name
        };
        if (d.custom_assigned_employee) v.employee = d.custom_assigned_employee;
        if (d.company) v.company = d.company;
        if (customer) v.customer = customer;
        frappe.new_doc("Site Visit", v);
    } else if (key === "quotation") {
        frappe.model.open_mapped_doc({ method: "erpnext.crm.doctype.lead.lead.make_quotation", frm: frm });
    } else if (key === "customer") {
        frappe.model.open_mapped_doc({ method: "erpnext.crm.doctype.lead.lead.make_customer", frm: frm });
    }
}

/* ------------------------------- RENDER ------------------------------- */

function lws_card(stage, data, current_stage) {
    const cat = lws_cat(stage, data);
    const exists = data && data.exists;
    const is_current = current_stage && current_stage.key === stage.key;
    let status_text = exists ? lws_status(data.status) : (stage.optional ? "Not Applicable" : (stage.key === "customer" ? "Not Converted" : "Not Created"));

    let cls = "cws-stage-card cws-cat-" + cat;
    if (!exists && stage.optional) cls += " cws-skipped";
    if (is_current) cls += " cws-current";

    const optional_html = stage.optional ? `<div class="cws-badge cws-badge-optional">Optional</div>` : "";
    const current_html = is_current ? `<div class="cws-badge cws-badge-current">Current</div>` : "";
    const name_html = exists && stage.key !== "lead" ? `<div class="lws-docname">${lws_esc(data.name)}${data.count > 1 ? ` +${data.count - 1}` : ""}</div>` : "";
    const date_html = exists && data.creation ? `<div class="cws-stage-date">${lws_dt(data.creation)}</div>` : "";

    return `
        <div class="${cls}" data-stage-key="${stage.key}" title="${exists ? "Open " : "Create "}${lws_esc(stage.title)}">
            ${optional_html}${current_html}
            <div class="cws-stage-icon">${stage.icon}</div>
            <div class="cws-stage-number">${stage.no}. ${lws_esc(stage.title)}</div>
            <div class="cws-stage-status">${lws_esc(status_text)}</div>
            ${name_html}${date_html}
        </div>`;
}

function lws_render(frm, field, stage_data, records, current_stage) {
    const cust = stage_data.customer;
    const current_data = stage_data[current_stage.key];

    const header = `
        <div class="cws-header">
            <div class="cws-header-title">
                <div class="cws-main-title">Lead Work Stage</div>
                <div class="cws-subtitle">Track every document created from this lead until it becomes a customer.</div>
            </div>
            <div class="cws-header-item">
                <div class="cws-label">Current Stage</div>
                <div class="cws-current-stage"><span class="cws-dot cws-dot-${lws_cat(current_stage, current_data)}"></span>${lws_esc(current_stage.title)}</div>
            </div>
            <div class="cws-header-item">
                <div class="cws-label">Lead</div>
                <div class="cws-value">${lws_esc(frm.doc.lead_name || frm.doc.name)}</div>
            </div>
            <div class="cws-header-item">
                <div class="cws-label">Customer</div>
                <div class="cws-value ${cust.exists ? "lws-link" : ""}" ${cust.exists ? `data-record-doctype="Customer" data-record-name="${lws_esc(cust.name)}"` : ""}>${cust.exists ? lws_esc(cust.customer_name || cust.name) : "Not Converted"}</div>
            </div>
            <div class="cws-header-item">
                <div class="cws-label">Last Updated</div>
                <div class="cws-value">${lws_dt(current_data && current_data.modified)}</div>
            </div>
        </div>`;

    let flow = `<div class="cws-workflow"><div class="cws-row">`;
    LWS_STAGES.forEach((s, i) => {
        flow += lws_card(s, stage_data[s.key], current_stage);
        if (i < LWS_STAGES.length - 1) flow += `<div class="cws-arrow">\u2192</div>`;
    });
    flow += `</div></div>`;

    // All linked documents (every record, not just the latest)
    const all = [];
    ["loan", "site_visit", "quotation", "customer"].forEach(k => {
        const stage = LWS_STAGES.find(s => s.key === k);
        (records[k] || []).forEach(r => all.push({ stage, r }));
    });
    all.sort((a, b) => new Date(b.r.modified) - new Date(a.r.modified));

    let rows = "";
    if (!all.length) {
        rows = `<div class="cws-no-activity">No documents created from this lead yet. Click a stage card above to create one.</div>`;
    } else {
        all.forEach((a, i) => {
            const cat = lws_cat(a.stage, Object.assign({ exists: true }, a.r));
            rows += `
                <div class="cws-activity-row lws-doc-row" data-record-doctype="${lws_esc(a.stage.doctype)}" data-record-name="${lws_esc(a.r.name)}">
                    <div>${i + 1}</div>
                    <div class="cws-activity-name"><span class="cws-dot cws-dot-${cat}"></span>${lws_esc(a.stage.key === "customer" ? "Customer" : a.stage.title)} \u2014 ${lws_esc(a.r.name)}</div>
                    <div>${lws_esc(lws_status(a.r.status))}</div>
                    <div>${lws_dt(a.r.modified)}</div>
                    <div>${lws_esc(a.r.owner || "\u2014")}</div>
                </div>`;
        });
    }

    const lower = `
        <div class="cws-bottom-grid">
            <div class="cws-panel">
                <div class="cws-panel-title"><span class="cws-title-icon">\u25c9</span> Stage Details</div>
                <div class="cws-detail-body">
                    <div class="cws-detail-row"><span>Current Stage</span><strong>${lws_esc(current_stage.title)}</strong></div>
                    <div class="cws-detail-row"><span>Status</span><strong class="cws-status-pill cws-status-${lws_cat(current_stage, current_data)}">${lws_esc(lws_status(current_data && current_data.status))}</strong></div>
                    <div class="cws-detail-row"><span>Started On</span><strong>${lws_dt(current_data && current_data.creation)}</strong></div>
                    <div class="cws-detail-row"><span>Assigned To</span><strong>${lws_esc((current_data && current_data.assigned_to) || "\u2014")}</strong></div>
                    <div class="cws-detail-row"><span>Record</span><strong>${lws_esc((current_data && current_data.name) || "\u2014")}</strong></div>
                </div>
            </div>
            <div class="cws-panel">
                <div class="cws-panel-title"><span class="cws-title-icon">\u2630</span> Linked Documents</div>
                <div class="cws-activity-table">
                    <div class="cws-activity-head lws-doc-row"><div>#</div><div>Document</div><div>Status</div><div>Updated</div><div>By</div></div>
                    ${rows}
                </div>
            </div>
        </div>`;

    field.$wrapper.html(`<style>${LWS_CSS}</style><div class="cws-container">${header}${flow}${lower}</div>`);

    field.$wrapper.find(".cws-stage-card").on("click", function () {
        const key = $(this).attr("data-stage-key");
        const stage = LWS_STAGES.find(s => s.key === key);
        const data = stage_data[key];
        if (key === "lead") { frm.scroll_to_field("first_name"); return; }
        if (data && data.exists && data.name) { frappe.set_route("Form", stage.doctype, data.name); return; }
        const msg = key === "customer"
            ? "This lead has not been converted yet. Convert it to a Customer now? All linked Loan, Site Visit and Quotation records will be carried over automatically."
            : `No ${stage.title} has been created from this lead. Create one now?`;
        frappe.confirm(msg, () => lws_create(frm, key, cust.exists ? cust.name : null));
    });

    field.$wrapper.find("[data-record-name]").not(".cws-stage-card").on("click", function () {
        const dt = $(this).attr("data-record-doctype");
        const dn = $(this).attr("data-record-name");
        if (dt && dn) frappe.set_route("Form", dt, dn);
    });
}

