// Solar Package Template - live totals and default item rate

function spt_recalc(frm) {
	let total = 0;
	(frm.doc.package_items || []).forEach((row) => {
		const amount = flt(row.qty) * (flt(row.rate) - flt(row.discount_amount));
		if (flt(row.amount) !== amount) {
			row.amount = amount;
		}
		total += amount;
	});
	frm.refresh_field("package_items");
	frm.set_value("no_of_items", (frm.doc.package_items || []).length);
	frm.set_value("total_amount", total);
	frm.set_value("net_package_amount", total - flt(frm.doc.package_discount));
}

frappe.ui.form.on("Solar Package Template", {
	refresh(frm) {
		frm.set_query("item_code", "package_items", () => ({ filters: { disabled: 0, is_sales_item: 1 } }));
	},
	package_discount(frm) {
		spt_recalc(frm);
	},
	package_items_remove(frm) {
		spt_recalc(frm);
	},
});

frappe.ui.form.on("Solar Package Template Item", {
	item_code(frm, cdt, cdn) {
		const row = locals[cdt][cdn];
		if (!row.item_code || flt(row.rate)) {
			spt_recalc(frm);
			return;
		}
		// Prefill Rate from the Standard Selling price list, if the item has a price there.
		frappe.db
			.get_value(
				"Item Price",
				{ item_code: row.item_code, price_list: "Standard Selling", selling: 1 },
				"price_list_rate"
			)
			.then((r) => {
				const price = r && r.message && r.message.price_list_rate;
				if (price && !flt(row.rate)) {
					frappe.model.set_value(cdt, cdn, "rate", price);
				} else {
					spt_recalc(frm);
				}
			});
	},
	qty(frm) {
		spt_recalc(frm);
	},
	rate(frm) {
		spt_recalc(frm);
	},
	discount_amount(frm) {
		spt_recalc(frm);
	},
});

// Quotation - Load Solar Package
// Copies a Solar Package Template's items into the quotation (a snapshot, not a live link).

function sq_wait_for_ajax() {
	return new Promise((resolve) => frappe.after_ajax(() => resolve()));
}

function sq_has_items(frm) {
	return (frm.doc.items || []).some((row) => row.item_code);
}

async function sq_load_package(frm, pkg, mode) {
	if (!pkg.package_items || !pkg.package_items.length) {
		frappe.msgprint(__("Package {0} has no items.", [pkg.package_name]));
		return;
	}

	frappe.dom.freeze(__("Loading package {0}...", [pkg.package_name]));
	try {
		if (mode === "replace") {
			frm.clear_table("items");
		} else {
			// drop empty placeholder rows before appending
			frm.doc.items = (frm.doc.items || []).filter((row) => row.item_code);
		}
		frm.refresh_field("items");

		for (const src of pkg.package_items) {
			const row = frm.add_child("items");
			await frappe.model.set_value(row.doctype, row.name, "item_code", src.item_code);
			await sq_wait_for_ajax();
			await frappe.model.set_value(row.doctype, row.name, "qty", flt(src.qty) || 1);
			await sq_wait_for_ajax();
			// Template rate becomes the list rate; template discount becomes the per-unit discount.
			await frappe.model.set_value(row.doctype, row.name, "price_list_rate", flt(src.rate));
			await sq_wait_for_ajax();
			await frappe.model.set_value(row.doctype, row.name, "discount_amount", flt(src.discount_amount));
			await sq_wait_for_ajax();
			if (flt(row.rate) !== flt(src.rate) - flt(src.discount_amount)) {
				await frappe.model.set_value(row.doctype, row.name, "rate", flt(src.rate) - flt(src.discount_amount));
				await sq_wait_for_ajax();
			}
		}

		const pkg_discount = flt(pkg.package_discount);
		if (pkg_discount) {
			const existing = mode === "replace" ? 0 : flt(frm.doc.discount_amount);
			await frm.set_value("apply_discount_on", "Net Total");
			await frm.set_value("discount_amount", existing + pkg_discount);
		} else if (mode === "replace" && flt(frm.doc.discount_amount)) {
			await frm.set_value("discount_amount", 0);
		}

		frm.refresh_field("items");
		frappe.show_alert(
			{
				message: __("Loaded {0} items from {1}", [pkg.package_items.length, pkg.package_name]),
				indicator: "green",
			},
			5
		);
	} finally {
		frappe.dom.unfreeze();
	}
}

async function sq_apply_package(frm, from_button) {
	const package_name = frm.doc.custom_solar_package;
	if (!package_name || frm.doc.docstatus !== 0) return;

	// Package that was loaded before this change (kept on the doc object, not saved)
	const previous = frm.doc.__sq_prev;
	const switching = !from_button && previous && previous !== package_name;

	const pkg = await frappe.db.get_doc("Solar Package Template", package_name);
	if (pkg.total_capacity) await frm.set_value("custom_total_capacity", pkg.total_capacity);
	if (pkg.roof_type) await frm.set_value("custom_roof_type", pkg.roof_type);

	// Switching packages (e.g. Test -> Test 2): old package items go, new ones come in.
	if (switching || !sq_has_items(frm)) {
		await sq_load_package(frm, pkg, "replace");
		frm.doc.__sq_prev = package_name;
		if (switching) {
			frappe.show_alert({ message: __("Replaced {0} items with {1}", [previous, package_name]), indicator: "green" }, 5);
		}
		return;
	}

	const d = new frappe.ui.Dialog({
		title: __("Load {0}", [pkg.package_name]),
		fields: [
			{
				fieldtype: "HTML",
				options: `<p>${__("This quotation already has items. What should happen to them?")}</p>`,
			},
		],
		primary_action_label: __("Replace Items"),
		primary_action() {
			d.hide();
			sq_load_package(frm, pkg, "replace").then(() => (frm.doc.__sq_prev = package_name));
		},
		secondary_action_label: __("Add Package Items"),
		secondary_action() {
			d.hide();
			sq_load_package(frm, pkg, "append").then(() => (frm.doc.__sq_prev = package_name));
		},
	});
	d.show();
}

frappe.ui.form.on("Quotation", {
	setup(frm) {
		// All active packages, whatever the roof type, so a package can always be switched.
		frm.set_query("custom_solar_package", () => ({ filters: { is_active: 1 } }));
	},
	refresh(frm) {
		if (frm.doc.__sq_prev === undefined) frm.doc.__sq_prev = frm.doc.custom_solar_package || "";
		if (frm.doc.docstatus === 0 && frm.doc.custom_solar_package) {
			frm.add_custom_button(__("Load Package"), () => sq_apply_package(frm, true), __("Solar"));
		}
	},
	custom_solar_package(frm) {
		sq_apply_package(frm);
	},
});

