async function pi_render(frm) {
	const field = frm.fields_dict.custom_print_images_panel;
	if (!field) return;
	const $w = field.$wrapper.empty();
	if (!document.getElementById("pi-style")) $("<style id='pi-style'>").text(PI_CSS).appendTo("head");

	if (frm.is_new()) {
		$w.html(`<div class="text-muted">${__("Save the quotation first, then come back here to add the images for its print.")}</div>`);
		return;
	}
	if (!frm.__pi_formats) {
		const r = await frappe.call({ method: "print_images_get_slots", args: { doctype: frm.doctype } });
		frm.__pi_formats = r.message || [];
	}
	const formats = frm.__pi_formats;
	if (!formats.length) {
		$w.html(`<div class="text-muted">${__("None of the Quotation print formats use images yet. To add some, open the Print Format and fill its Image Slots table.")}</div>`);
		return;
	}
	const used = (frm.doc.custom_print_images || []).map((r) => r.print_format);
	const pick =
		formats.find((f) => f.print_format === frm.__pi_pf) ||
		formats.find((f) => f.print_format === frm.meta.default_print_format) ||
		formats.find((f) => used.includes(f.print_format)) ||
		formats[0];
	frm.__pi_pf = pick.print_format;

	const esc = frappe.utils.escape_html;
	const can_default = frappe.user.has_role("System Manager") || frappe.user.has_role("Sales Manager");
	const locked = frm.doc.docstatus === 2;

	const options = formats
		.map((f) => `<option value="${esc(f.print_format)}" ${f === pick ? "selected" : ""}>${esc(f.print_format)}</option>`)
		.join("");
	const cards = pick.slots
		.map((s, i) => {
			const own = pi_current(frm, pick.print_format, s);
			const url = own || s.default_image || "";
			const badge = own
				? `<span class="pi-badge own">${__("This quotation")}</span>`
				: url
				? `<span class="pi-badge">${__("Default")}</span>`
				: "";
			const prev = url
				? `<img src="${esc(url)}">${badge}`
				: `<div class="pi-empty">${__("No image yet")}</div>`;
			return `<div class="pi-card" data-slot="${i}">
				<h5>${i + 1}. ${esc(s.label)}</h5>
				<div class="pi-hint">${esc(s.hint || "")}</div>
				<div class="pi-prev">${prev}</div>
				${locked ? "" : `<div class="pi-actions">
					<button class="btn btn-xs btn-primary" data-up="${i}">${own ? __("Change") : __("Upload")}</button>
					${own ? `<button class="btn btn-xs btn-default" data-rm="${i}">${__("Remove")}</button>` : ""}
				</div><div class="pi-droptip">${__("or drop an image here")}</div>`}
			</div>`;
		})
		.join("");

	$w.html(`<div class="pi-wrap">
		<div class="pi-top">
			<b>${__("Print format")}</b>
			${formats.length > 1 ? `<select class="form-control input-sm pi-pf">${options}</select>` : `<span>${esc(pick.print_format)}</span>`}
		</div>
		${pick.slots.length ? `<div class="pi-sub">${__("{0} uses {1} image(s). Upload them here. A slot marked Default uses the standard image unless you upload one for this quotation.", [esc(pick.print_format), pick.slots.length])}</div>
		<div class="pi-grid">${cards}</div>` : ""}
		${can_default && !locked && pick.slots.length ? `<div class="pi-foot"><button class="btn btn-xs btn-default pi-def">${__("Use this quotation's images as the defaults for {0}", [esc(pick.print_format)])}</button></div>` : ""}
	</div>`);

	if (pick.extra_pages && !locked) pi_render_pages(frm, pick, $w.find(".pi-wrap"), can_default);
	else if (pick.extra_pages) pi_render_pages(frm, pick, $w.find(".pi-wrap"), false, true);

	pi_guard($w[0]);

	$w.find(".pi-pf").on("change", function () {
		frm.__pi_pf = $(this).val();
		pi_render(frm);
	});
	$w.find("[data-up]").on("click", function () {
		const s = pick.slots[+$(this).attr("data-up")];
		pi_pick_file(frm, (url) => pi_set(frm, pick.print_format, s, url));
	});
	if (!locked) {
		$w.find("[data-slot]").each(function () {
			const s = pick.slots[+$(this).attr("data-slot")];
			pi_dropzone(this, async (file) => {
				const url = await pi_upload_file(frm, file);
				if (url) await pi_set(frm, pick.print_format, s, url);
			});
		});
	}
	$w.find("[data-rm]").on("click", function () {
		const s = pick.slots[+$(this).attr("data-rm")];
		pi_set(frm, pick.print_format, s, "");
	});
	$w.find(".pi-def").on("click", async () => {
		const images = {};
		pick.slots.forEach((s) => {
			const u = pi_current(frm, pick.print_format, s);
			if (u) images[s.label] = u;
		});
		if (!Object.keys(images).length) {
			frappe.msgprint(__("Upload at least one image on this quotation first."));
			return;
		}
		frappe.confirm(__("Make these images the defaults for every future quotation printed with {0}?", [esc(pick.print_format)]), async () => {
			await frappe.call({ method: "print_images_set_defaults", args: { print_format: pick.print_format, images: JSON.stringify(images) } });
			frm.__pi_formats = null;
			frappe.show_alert({ message: __("Defaults saved for {0}", [pick.print_format]), indicator: "green" }, 5);
			pi_render(frm);
		});
	});
}

function pi_row(frm, pf, slot) {
	return (frm.doc.custom_print_images || []).find((r) => r.print_format === pf && r.slot === slot);
}

function pi_current(frm, pf, s) {
	if (s.quotation_field) return frm.doc[s.quotation_field] || "";
	const row = pi_row(frm, pf, s.label);
	return (row && row.image) || "";
}

async function pi_set(frm, pf, s, url) {
	if (s.quotation_field) {
		frm.doc[s.quotation_field] = url;
		frm.dirty();
	} else {
		const row = pi_row(frm, pf, s.label);
		if (url) {
			const r = row || frm.add_child("custom_print_images", { print_format: pf, slot: s.label });
			r.image = url;
		} else if (row) {
			frappe.model.clear_doc(row.doctype, row.name);
		}
		frm.dirty();
	}
	await frm.save(frm.doc.docstatus === 1 ? "Update" : undefined);
	frappe.show_alert({ message: __("{0} saved", [s.label]), indicator: "green" }, 3);
}

// ---------------- Extra pages ----------------

function pi_page_rows(frm, pf) {
	return (frm.doc.custom_print_extra_pages || []).filter((r) => r.print_format === pf);
}

// Defaults merged with this quotation's rows. A quotation row with no image skips the default.
function pi_pages(frm, pick) {
	const by = {};
	(pick.default_pages || []).forEach((d) => (by[d.page_no] = { page_no: d.page_no, def: d }));
	pi_page_rows(frm, pick.print_format).forEach((r) => {
		by[r.page_no] = Object.assign(by[r.page_no] || { page_no: r.page_no }, { own: r });
	});
	return Object.values(by)
		.filter((p) => p.def || (p.own && p.own.image))
		.sort((a, b) => a.page_no - b.page_no)
		.map((p) => {
			p.state = p.own ? (p.own.image ? "own" : "skipped") : "default";
			p.image = p.own && p.own.image ? p.own.image : p.def ? p.def.image : "";
			p.label = (p.own && p.own.label) || (p.def && p.def.label) || "";
			return p;
		});
}

function pi_render_pages(frm, pick, $wrap, can_default, readonly) {
	const esc = frappe.utils.escape_html;
	const pages = pi_pages(frm, pick);
	const badge = { own: ["own", __("This quotation")], default: ["", __("All quotations")], skipped: ["skip", __("Skipped")] };
	const cards = pages
		.map((p, i) => {
			const b = badge[p.state];
			let btns = "";
			if (!readonly) {
				if (p.state === "own")
					btns = `<button class="btn btn-xs btn-primary" data-xedit="${i}">${__("Edit")}</button>
						<button class="btn btn-xs btn-default" data-xrm="${i}">${p.def ? __("Use default") : __("Remove")}</button>`;
				else if (p.state === "default")
					btns = `<button class="btn btn-xs btn-primary" data-xrep="${i}">${__("Replace")}</button>
						<button class="btn btn-xs btn-default" data-xskip="${i}">${__("Skip")}</button>`;
				else btns = `<button class="btn btn-xs btn-default" data-xrm="${i}">${__("Print it again")}</button>`;
			}
			return `<div class="pi-card ${p.state === "skipped" ? "pi-skipped" : ""}" data-xi="${i}">
				<h5>${__("Page {0}", [p.page_no])}${p.label ? " · " + esc(p.label) : ""}</h5>
				<div class="pi-prev">${p.image ? `<img src="${esc(p.image)}">` : `<div class="pi-empty">${__("No image")}</div>`}<span class="pi-badge ${b[0]}">${b[1]}</span></div>
				${btns ? `<div class="pi-actions">${btns}</div>` : ""}
				${!readonly && can_default && p.state !== "skipped" ? `<label class="pi-all ${pi_is_all(p) ? "is-on" : ""}"><input type="checkbox" data-xall="${i}" ${pi_is_all(p) ? "checked" : ""}>${__("Use on all {0} quotations", [esc(pick.print_format)])}</label>` : ""}
				${btns ? `<div class="pi-droptip">${__("or drop an image here")}</div>` : ""}
			</div>`;
		})
		.join("");

	const has_ft = !!frm.fields_dict.custom_extra_pages_footer;
	const ft_on = !!frm.doc.custom_extra_pages_footer;
	const ft_toggle = has_ft && pages.length
		? `<label class="pi-all pi-ft ${ft_on ? "is-on" : ""}"><input type="checkbox" class="pi-ftoggle" ${ft_on ? "checked" : ""} ${readonly ? "disabled" : ""}>${__("Show footer on extra pages")}</label>`
		: "";

	const $x = $(`<div class="pi-xp">
		<h4>${__("Extra pages")}</h4>
		<div class="pi-sub">${__("Full-page images (brochure, datasheet, warranty card…) printed as a whole A4 page at the page number you give. The quotation's own pages fill the other numbers in order.")}${can_default ? " " + __("Tick <b>Use on all {0} quotations</b> on a page to add it to every quotation printed with this format.", [esc(pick.print_format)]) : ""}</div>
		${ft_toggle}
		<div class="pi-grid">${cards}${readonly ? "" : `<button class="pi-add"><span>+ ${__("Add page")}<div class="pi-droptip">${__("click, or drop an image here")}</div></span></button>`}</div>
	</div>`).appendTo($wrap);
	if (readonly) return;

	$x.find(".pi-ftoggle").on("change", async function () {
		const on = this.checked;
		this.disabled = true;
		frm.doc.custom_extra_pages_footer = on ? 1 : 0;
		await pi_save(frm, on ? __("Footer will print on the extra pages") : __("Extra pages will print without the footer"));
	});

	const pf = pick.print_format;
	const upload = (cb) => pi_pick_file(frm, cb);
	const next_free = () => {
		const used = pages.filter((p) => p.state !== "skipped").map((p) => p.page_no);
		let n = 2;
		while (used.includes(n)) n++;
		return n;
	};
	const set_row = (page_no, vals) => {
		let r = pi_page_rows(frm, pf).find((x) => x.page_no === page_no);
		if (!r) r = frm.add_child("custom_print_extra_pages", { print_format: pf, page_no });
		Object.assign(r, vals);
		return r;
	};
	const ask = (title, p, image) => {
		const d = new frappe.ui.Dialog({
			title,
			fields: [
				{ fieldname: "page_no", fieldtype: "Int", label: __("Print at page number"), reqd: 1, default: p ? p.page_no : next_free() },
				{ fieldname: "label", fieldtype: "Data", label: __("Label"), description: __("Optional, e.g. Brochure"), default: p ? p.label : "" },
			],
			primary_action_label: __("Save"),
			primary_action: async (v) => {
				if (v.page_no < 1) return frappe.msgprint(__("Page number must be 1 or more."));
				const clash = pages.find((x) => x.page_no === v.page_no && x.state !== "skipped" && (!p || x.page_no !== p.page_no));
				if (clash) return frappe.msgprint(__("Page {0} is already used. Choose another number, or remove that page first.", [v.page_no]));
				d.hide();
				if (p && p.own && p.page_no !== v.page_no) frappe.model.clear_doc(p.own.doctype, p.own.name);
				set_row(v.page_no, { image, label: v.label || "" });
				await pi_save(frm, __("Page {0} saved", [v.page_no]));
			},
		});
		if (p) {
			d.set_secondary_action_label(__("Replace image"));
			d.set_secondary_action(() =>
				upload((url) => {
					image = url;
					frappe.show_alert({ message: __("New image ready. Press Save."), indicator: "blue" }, 4);
				})
			);
		}
		d.show();
	};

	$x.find(".pi-add").on("click", () => upload((url) => ask(__("Add extra page"), null, url)));
	pi_dropzone($x.find(".pi-add")[0], async (file) => {
		const url = await pi_upload_file(frm, file);
		if (url) ask(__("Add extra page"), null, url);
	});
	$x.find("[data-xi]").each(function () {
		const p = pages[+$(this).attr("data-xi")];
		pi_dropzone(this, async (file) => {
			const url = await pi_upload_file(frm, file);
			if (!url) return;
			set_row(p.page_no, { image: url, label: p.label });
			await pi_save(frm, __("Page {0} image replaced", [p.page_no]));
		});
	});
	$x.find("[data-xedit]").on("click", function () {
		const p = pages[+$(this).attr("data-xedit")];
		ask(__("Edit page {0}", [p.page_no]), p, p.own.image);
	});
	$x.find("[data-xrep]").on("click", function () {
		const p = pages[+$(this).attr("data-xrep")];
		upload(async (url) => {
			set_row(p.page_no, { image: url, label: p.label });
			await pi_save(frm, __("Page {0} replaced for this quotation", [p.page_no]));
		});
	});
	$x.find("[data-xskip]").on("click", async function () {
		const p = pages[+$(this).attr("data-xskip")];
		set_row(p.page_no, { image: "", label: p.label });
		await pi_save(frm, __("Page {0} will not print on this quotation", [p.page_no]));
	});
	$x.find("[data-xrm]").on("click", async function () {
		const p = pages[+$(this).attr("data-xrm")];
		frappe.model.clear_doc(p.own.doctype, p.own.name);
		await pi_save(frm, __("Page {0} updated", [p.page_no]));
	});
	$x.find("[data-xall]").on("change", async function () {
		const p = pages[+$(this).attr("data-xall")];
		const on = this.checked;
		this.disabled = true;
		const defs = (pick.default_pages || []).filter((d) => d.page_no !== p.page_no)
			.map((d) => ({ page_no: d.page_no, label: d.label, image: d.image }));
		if (on) defs.push({ page_no: p.page_no, label: p.label, image: p.image });
		try {
			await frappe.call({ method: "print_images_set_default_pages", args: { print_format: pf, pages: JSON.stringify(defs) } });
		} catch (e) {
			this.checked = !on;
			this.disabled = false;
			return;
		}
		frm.__pi_formats = null;
		const own = p.own;
		if (on) {
			// now standard for every quotation: this quotation no longer needs its own copy
			if (own) frappe.model.clear_doc(own.doctype, own.name);
			if (own) await pi_save(frm, __("Page {0} will now print on all {1} quotations", [p.page_no, pf]));
			else { frappe.show_alert({ message: __("Page {0} will now print on all {1} quotations", [p.page_no, pf]), indicator: "green" }, 4); pi_render(frm); }
		} else {
			// keep it on this quotation only
			if (!own || !own.image) set_row(p.page_no, { image: p.image, label: p.label });
			await pi_save(frm, __("Page {0} now prints on this quotation only", [p.page_no]));
		}
	});
}

async function pi_save(frm, msg) {
	frm.refresh_field("custom_print_extra_pages");
	frm.dirty();
	await frm.save(frm.doc.docstatus === 1 ? "Update" : undefined);
	frappe.show_alert({ message: msg, indicator: "green" }, 4);
}

// ---------------- Drag and drop ----------------

// Upload an image at full quality: public, attached to this quotation, and NOT "optimized"
// (Frappe's optimize shrinks images to 1024 x 768, which makes full-page prints blurry).
async function pi_upload_file(frm, file) {
	if (!/^image\//.test(file.type || "") && !/\.(jpe?g|png|webp|gif)$/i.test(file.name || "")) {
		frappe.msgprint(__("Please drop an image file (JPG or PNG)."));
		return null;
	}
	const fd = new FormData();
	fd.append("file", file, file.name);
	fd.append("is_private", "0");
	fd.append("doctype", frm.doctype);
	fd.append("docname", frm.docname);
	frappe.show_alert({ message: __("Uploading {0}…", [frappe.utils.escape_html(file.name)]), indicator: "blue" }, 3);
	try {
		const res = await fetch("/api/method/upload_file", {
			method: "POST",
			body: fd,
			headers: { Accept: "application/json", "X-Frappe-CSRF-Token": frappe.csrf_token },
		});
		const j = await res.json().catch(() => ({}));
		if (!res.ok || !j.message || !j.message.file_url) throw new Error((j && j.exception) || res.statusText);
		return j.message.file_url;
	} catch (e) {
		frappe.msgprint(__("Could not upload {0}. Try the Upload button instead.", [frappe.utils.escape_html(file.name)]));
		return null;
	}
}

// Make an element accept one dropped file.
function pi_dropzone(el, on_file) {
	if (!el) return;
	let depth = 0;
	const has_files = (e) => e.dataTransfer && Array.from(e.dataTransfer.types || []).includes("Files");
	el.addEventListener("dragenter", (e) => {
		if (!has_files(e)) return;
		e.preventDefault();
		depth++;
		el.classList.add("pi-drop-ok");
	});
	el.addEventListener("dragover", (e) => {
		if (!has_files(e)) return;
		e.preventDefault();
		e.dataTransfer.dropEffect = "copy";
	});
	el.addEventListener("dragleave", () => {
		depth = Math.max(0, depth - 1);
		if (!depth) el.classList.remove("pi-drop-ok");
	});
	el.addEventListener("drop", (e) => {
		if (!has_files(e)) return;
		e.preventDefault();
		e.stopPropagation();
		depth = 0;
		el.classList.remove("pi-drop-ok");
		const file = e.dataTransfer.files && e.dataTransfer.files[0];
		if (file) on_file(file);
	});
}

// Dropping a file on the panel but outside a box must not open the image in the tab.
function pi_guard(el) {
	if (!el || el.__pi_guard) return;
	el.__pi_guard = true;
	el.addEventListener("dragover", (e) => e.preventDefault());
	el.addEventListener("drop", (e) => {
		e.preventDefault();
		if (e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files.length)
			frappe.show_alert({ message: __("Drop the image onto one of the boxes."), indicator: "orange" }, 3);
	});
}

// Let the user pick an image from their device, then upload it at full quality.
function pi_pick_file(frm, cb) {
	const inp = document.createElement("input");
	inp.type = "file";
	inp.accept = "image/*";
	inp.style.display = "none";
	inp.addEventListener("change", async () => {
		const f = inp.files && inp.files[0];
		inp.remove();
		if (!f) return;
		const url = await pi_upload_file(frm, f);
		if (url) cb(url);
	});
	document.body.appendChild(inp);
	inp.click();
}

// A page is "on all quotations" when it is a default and this quotation shows that same image.
function pi_is_all(p) {
	return !!(p.def && (!p.own || p.own.image === p.def.image));
}

// Quotation - Notes Template
// Picking a Notes Template fills the "Notes (on print)" box with its notes.
frappe.ui.form.on("Quotation", {
	async custom_quote_notes_template(frm) {
		const t = frm.doc.custom_quote_notes_template;
		if (!t) return;
		const r = await frappe.db.get_value("Quotation Notes Template", t, "notes");
		frm.set_value("custom_quote_notes", (r.message && r.message.notes) || "");
	},
});

frappe.ui.form.on("Quotation", "onload", (frm) => {
	frm.set_query("custom_quote_notes_template", () => ({ filters: { disabled: 0 } }));
});

