const sp_switch = (on) => `<label class="sp-sw"><input type="checkbox" ${on ? "checked" : ""}><span></span></label>`;

function sp_rows(frm) {
	return (frm.doc.custom_package_sections || []).slice().sort((a, b) => a.idx - b.idx);
}

function sp_render(frm) {
	const f = frm.fields_dict.custom_package_ui;
	if (!f) return;
	sp_css();
	const on = cint(frm.doc.custom_package_sections_enabled);
	const rows = sp_rows(frm);
	const $w = $(`<div>
		<div class="sp-intro">${__("Choose how the <b>Solar Package</b> form looks on this site. Switched off, a package has one plain item table. Switched on, items are split into coloured sections that you name here. Click <b>Save</b> when you are done.")}</div>
		<div class="sp-list"></div>
	</div>`);
	const $l = $w.find(".sp-list");

	const $master = $(`<div class="sp-card master">
		${sp_switch(on)}
		<div class="sp-text">
			<div class="sp-title">${__("Show Solar Package in sections")}</div>
			<div class="sp-sub">${on ? __("On: each package shows the sections below.") : __("Off: each package shows one item table.")}</div>
		</div>
	</div>`);
	$master.find("input").on("change", function () {
		frm.set_value("custom_package_sections_enabled", this.checked ? 1 : 0).then(() => sp_render(frm));
	});
	$l.append($master);

	if (on) {
		$l.append(`<div class="sp-h">${__("Sections")}</div>
			<div class="sp-hsub">${__("Shown in this order on every package. Only section 1 is counted in the package amount and loaded into the quotation.")}</div>`);

		// section 1: the main table, always there
		const mc = sp_color(frm.doc.custom_main_section_color, "#2563eb");
		const $main = $(`<div class="sp-card">
			<span class="sp-badge" style="background:${mc}">1</span>
			<div class="sp-text">
				<div class="sp-title" style="color:${mc}">${sp_esc(frm.doc.custom_main_section_title || __("Main Package Items"))}<span class="sp-tag">${__("main · in quotation")}</span></div>
				<div class="sp-sub">${sp_esc(frm.doc.custom_main_section_subtitle || "")}</div>
			</div>
			<button type="button" class="sp-btn">${__("Edit")}</button>
		</div>`);
		$main.find(".sp-btn").on("click", () => sp_main_dialog(frm));
		$l.append($main);

		rows.forEach((r, i) => {
			const c = sp_color(r.color);
			const tags = [];
			if (!cint(r.show_rates)) tags.push(__("no rates"));
			if (!r.field_key) tags.push(__("new · Save to create"));
			const $c = $(`<div class="sp-card ${cint(r.enabled) ? "" : "off"}">
				${sp_switch(cint(r.enabled))}
				<span class="sp-badge" style="background:${c}">${i + 2}</span>
				<div class="sp-text">
					<div class="sp-title" style="color:${c}">${sp_esc(r.section_name)}${tags.map((t) => `<span class="sp-tag">${t}</span>`).join("")}</div>
					<div class="sp-sub">${sp_esc(r.subtitle || "")}</div>
				</div>
				<div class="sp-tools">
					<button type="button" class="sp-icon up" title="${__("Move up")}" ${i === 0 ? "disabled" : ""}>&#9650;</button>
					<button type="button" class="sp-icon down" title="${__("Move down")}" ${i === rows.length - 1 ? "disabled" : ""}>&#9660;</button>
					<button type="button" class="sp-btn edit">${__("Edit")}</button>
					<button type="button" class="sp-icon del" title="${__("Remove")}">&#10005;</button>
				</div>
			</div>`);
			$c.find("input").on("change", function () {
				frappe.model.set_value(r.doctype, r.name, "enabled", this.checked ? 1 : 0).then(() => sp_render(frm));
			});
			$c.find(".up").on("click", () => sp_move(frm, r, -1));
			$c.find(".down").on("click", () => sp_move(frm, r, 1));
			$c.find(".edit").on("click", () => sp_section_dialog(frm, r));
			$c.find(".del").on("click", () => {
				frappe.confirm(
					__("Remove the section <b>{0}</b>? It disappears from Solar Package. Items already saved in it are kept (hidden), and come back if you add a section with the same name again.", [sp_esc(r.section_name)]),
					() => {
						frm.doc.custom_package_sections = sp_rows(frm).filter((x) => x.name !== r.name);
						frm.doc.custom_package_sections.forEach((x, k) => (x.idx = k + 1));
						frm.refresh_field("custom_package_sections");
						frm.dirty();
						sp_render(frm);
					}
				);
			});
			$l.append($c);
		});

		const $add = $(`<div class="sp-add">+ ${__("Add a section")}</div>`);
		$add.on("click", () => sp_section_dialog(frm, null));
		$l.append($add);
	}

	f.$wrapper.empty().append($w);
	const hidden = frm.fields_dict.custom_package_sections.df.hidden;
	const $a = $(`<div class="sp-adv">${hidden ? __("Show advanced fields") : __("Hide advanced fields")}</div>`);
	$a.on("click", () => {
		SP_RAW.forEach((fn) => frm.set_df_property(fn, "hidden", hidden ? 0 : 1));
		sp_render(frm);
	});
	f.$wrapper.append($a);
}

function sp_move(frm, row, step) {
	const rows = sp_rows(frm);
	const i = rows.findIndex((x) => x.name === row.name);
	const j = i + step;
	if (i < 0 || j < 0 || j >= rows.length) return;
	[rows[i], rows[j]] = [rows[j], rows[i]];
	rows.forEach((x, k) => (x.idx = k + 1));
	frm.doc.custom_package_sections = rows;
	frm.refresh_field("custom_package_sections");
	frm.dirty();
	sp_render(frm);
}

function sp_section_dialog(frm, row) {
	const used = sp_rows(frm).map((r) => (r.color || "").toLowerCase());
	const next = SP_PALETTE.find((c) => !used.includes(c)) || SP_PALETTE[0];
	const d = new frappe.ui.Dialog({
		title: row ? __("Edit section") : __("Add a section"),
		fields: [
			{ fieldname: "section_name", fieldtype: "Data", label: __("Section name"), reqd: 1,
				description: __("For example: Fixed Items (Not shown in quotation)"), default: row ? row.section_name : "" },
			{ fieldname: "subtitle", fieldtype: "Small Text", label: __("Line under the name"), default: row ? row.subtitle : "" },
			{ fieldname: "color", fieldtype: "Color", label: __("Colour"), reqd: 1, default: row ? sp_color(row.color) : next },
			{ fieldname: "show_rates", fieldtype: "Check", label: __("Show Rate, Discount and Amount columns"),
				default: row ? cint(row.show_rates) : 1 },
		],
		primary_action_label: row ? __("Update") : __("Add Section"),
		primary_action(v) {
			const name = (v.section_name || "").trim();
			if (!name) return;
			const dup = sp_rows(frm).find((r) => (!row || r.name !== row.name) && (r.section_name || "").trim().toLowerCase() === name.toLowerCase());
			if (dup) {
				frappe.msgprint(__("There is already a section called {0}.", [sp_esc(name)]));
				return;
			}
			const vals = { section_name: name, subtitle: v.subtitle || "", color: sp_color(v.color), show_rates: cint(v.show_rates) };
			if (row) {
				Object.assign(locals[row.doctype][row.name], vals);
			} else {
				const r = frm.add_child("custom_package_sections");
				Object.assign(r, vals, { enabled: 1 });
			}
			frm.refresh_field("custom_package_sections");
			frm.dirty();
			d.hide();
			sp_render(frm);
			frappe.show_alert({ message: __("Click Save to apply it to Solar Package."), indicator: "blue" });
		},
	});
	d.show();
}

function sp_main_dialog(frm) {
	const d = new frappe.ui.Dialog({
		title: __("Edit main section"),
		fields: [
			{ fieldname: "title", fieldtype: "Data", label: __("Section name"), reqd: 1, default: frm.doc.custom_main_section_title || __("Main Package Items") },
			{ fieldname: "subtitle", fieldtype: "Small Text", label: __("Line under the name"), default: frm.doc.custom_main_section_subtitle || "" },
			{ fieldname: "color", fieldtype: "Color", label: __("Colour"), reqd: 1, default: sp_color(frm.doc.custom_main_section_color, "#2563eb") },
		],
		primary_action_label: __("Update"),
		primary_action(v) {
			frm.set_value({
				custom_main_section_title: (v.title || "").trim(),
				custom_main_section_subtitle: v.subtitle || "",
				custom_main_section_color: sp_color(v.color, "#2563eb"),
			}).then(() => {
				d.hide();
				sp_render(frm);
			});
		},
	});
	d.show();
}

