// Solar Package Template - sections, set up in Solar Settings > Solar Package.
// Section 1 is always the main table (package_items, counted in the package amount and loaded into quotations).
// Every other section is a table that Solar Settings creates (custom_sec_*). When the setting is off,
// nothing here runs and the form stays a plain item table.

const SPS_FALLBACK = "#6b7280";
const sps_esc = (s) => frappe.utils.escape_html(s == null ? "" : String(s));
const sps_color = (c, d) => (/^#[0-9a-fA-F]{6}$/.test(c || "") ? c : d || SPS_FALLBACK);

function sps_load(frm) {
	if (!frm.__sps_p) {
		frm.__sps_p = frappe
			.xcall("solar_package_sections")
			.then((c) => c || { enabled: 0, sections: [] })
			.catch(() => ({ enabled: 0, sections: [] }));
	}
	return frm.__sps_p;
}

function sps_css() {
	if (document.getElementById("sps-style-cfg")) return;
	const s = document.createElement("style");
	s.id = "sps-style-cfg";
	s.textContent = `
		.sps-card > .section-head { display:none !important; }
		.sps-card .section-body { padding-top:4px !important; }
		.sps-head { display:flex; align-items:center; gap:12px; padding:12px 14px; background:var(--sps-t);
			border:1px solid var(--sps-b); border-bottom:none; border-radius:12px 12px 0 0; }
		.sps-badge { flex:0 0 30px; width:30px; height:30px; border-radius:50%; background:var(--sps-c); color:#fff;
			display:flex; align-items:center; justify-content:center; font-weight:700; font-size:15px; }
