	`;
	document.head.appendChild(s);
}

// main section + the configured sections that exist on this form
function sps_sections(frm, cfg) {
	const m = cfg.main || {};
	const list = [{
		field: "section_items", table: "package_items",
		title: m.title || __("Main Package Items"), sub: m.subtitle || "",
		color: sps_color(m.color, "#2563eb"), show_rates: 1,
	}];
	(cfg.sections || []).forEach((s) => list.push({
		field: s.key.replace("custom_sec_", "custom_secb_"), table: s.key,
		title: s.title, sub: s.subtitle || "", color: sps_color(s.color), show_rates: s.show_rates,
	}));
	return list.filter((s) => frm.fields_dict[s.table] && frm.fields_dict[s.table].grid);
}

function sps_columns(frm, sec) {
	const grid = frm.fields_dict[sec.table].grid;
	if (sec.show_rates || grid.__sps_cols) return;
	grid.__sps_cols = true;
	const was_dirty = frm.is_dirty();
	try {
		// own copies, so hiding columns here never touches the other item tables
		grid.docfields = (grid.docfields || []).map((df) => Object.assign({}, df));
		grid.docfields.forEach((df) => {
			if (["rate", "discount_amount", "amount"].includes(df.fieldname)) df.in_list_view = 0;
		});
		grid.visible_columns = null;
		grid.refresh();
	} catch (e) {
		console.warn("Solar Package sections: columns", e);
	}
	if (!was_dirty && frm.is_dirty()) {
		frm.doc.__unsaved = 0;
		frm.refresh_header();
	}
}

function sps_decorate(frm, cfg) {
	if (!cfg.enabled) return;
	sps_css();
	sps_sections(frm, cfg).forEach((sec, i) => {
		const tf = frm.fields_dict[sec.table];
		const sf = frm.fields_dict[sec.field];
		let $sec = $(tf.wrapper).closest(".form-section");
		if (!$sec.length && sf) $sec = $(sf.wrapper);
		$sec.addClass("sps-card").css({
			"--sps-c": sec.color,
			"--sps-t": sec.color + "14",
			"--sps-b": sec.color + "55",
		});
		const $field = $(tf.wrapper);
		$field.find("> .sps-head").remove();
		const $head = $(`<div class="sps-head">
			<span class="sps-badge">${i + 1}</span>
			<div class="sps-titles"><div class="sps-title">${sps_esc(sec.title)}</div>
				${sec.sub ? `<div class="sps-sub">${sps_esc(sec.sub)}</div>` : ""}</div>
			${frm.doc.docstatus === 0 && !tf.df.read_only ? `<button type="button" class="sps-add">+ ${__("Add Item")}</button>` : ""}
		</div>`);
		$head.find(".sps-add").on("click", (e) => {
			e.preventDefault();
			tf.grid.add_new_row(null, null, true);
		});
		$field.prepend($head);
		sps_columns(frm, sec);
	});
}

function sps_summary(frm) {
	const f = frm.fields_dict.custom_package_summary;
	if (!f || !frm.__sps_cfg) return;
	const cfg = frm.__sps_cfg;
	if (!cfg.enabled) {
		f.$wrapper.empty();
		return;
	}
	const chip = (label, v, c) =>
		`<span class="sps-chip">${c ? `<span class="sps-dot" style="background:${c}"></span>` : ""}${sps_esc(label)} <b>${v}</b></span>`;
	let total = 0;
	const chips = sps_sections(frm, cfg).map((sec) => {
		const n = (frm.doc[sec.table] || []).length;
		total += n;
		return chip(sec.title, n, sec.color);
	});
	const amt = format_currency(frm.doc.net_package_amount || 0, frappe.defaults.get_default("currency"));
	f.$wrapper.html(`<div class="sps-summary">${chips.join("")}
		${chip(__("Total items"), total)}${chip(__("Package amount"), amt)}</div>`);
}

// add / remove row handlers for the configured tables (registered once per table)
window.__sps_bound = window.__sps_bound || {};
function sps_bind(cfg) {
	const ev = {};
	(cfg.sections || []).forEach((s) => {
		if (window.__sps_bound[s.key]) return;
		window.__sps_bound[s.key] = 1;
		ev[s.key + "_add"] = sps_summary;
		ev[s.key + "_remove"] = sps_summary;
	});
	if (Object.keys(ev).length) frappe.ui.form.on("Solar Package Template", ev);
}

function sps_run(frm) {
	return sps_load(frm).then((cfg) => {
		frm.__sps_cfg = cfg;
		if (!cfg.enabled) {
			sps_summary(frm);
			return;
		}
		sps_bind(cfg);
		(cfg.sections || []).forEach((s) => {
			if (frm.fields_dict[s.key]) {
				frm.set_query("item_code", s.key, () => ({ filters: { disabled: 0 } }));
			}
		});
		sps_decorate(frm, cfg);
		sps_summary(frm);
		setTimeout(() => sps_decorate(frm, cfg), 300);
	});
}

frappe.ui.form.on("Solar Package Template", {
	onload(frm) {
		frm.__sps_p = null; // re-read the settings each time a package is opened
	},
	refresh(frm) {
		sps_run(frm);
	},
	net_package_amount: sps_summary,
	package_items_add: sps_summary,
	package_items_remove: sps_summary,
});

