}

function ss_remove_row(frm, table, name) {
    frm.doc[table] = (frm.doc[table] || []).filter((x) => x.name !== name);
    frm.doc[table].forEach((x, i) => (x.idx = i + 1));
    frm.refresh_field(table);
    frm.dirty();
}

function ss_new_notes(v, doc) {
    let n = "Always";
    if (v.show_when === "After Submit") n = "After the " + ss_nice(doc) + " is submitted";
    if (v.show_when === "Field has value") n = "When " + v.when_label + " is " + v.when_value;
    return n;
}

/* ---------------- Create buttons ---------------- */
function ss_render_create(frm) {
    const f = frm.fields_dict.create_ui;
    if (!f) return;
    const rows = frm.doc.create_buttons || [];
    const extra = frm.__ss_extra_docs || [];
    let docs = [];
    rows.forEach((r) => { if (r.document && !docs.includes(r.document)) docs.push(r.document); });
    extra.forEach((d) => { if (!docs.includes(d)) docs.push(d); });
    docs.sort((a, b) => {
        const ia = SS_ORDER.indexOf(a), ib = SS_ORDER.indexOf(b);
        return (ia < 0 ? 999 : ia) - (ib < 0 ? 999 : ib);
    });
    if (!frm.__ss_doc || !docs.includes(frm.__ss_doc)) frm.__ss_doc = docs[0];
    const cur = frm.__ss_doc;

    const $w = $(`<div>
        <div class="ss-intro">${__("Choose a document on the left. On the right, switch on the things people should be able to create from it. Click <b>Save</b> when you are done.")}</div>
        <div class="ss-wrap"><div class="ss-nav"></div><div class="ss-panel"></div></div>
    </div>`);
    const $nav = $w.find(".ss-nav");
    docs.forEach((d, i) => {
        const shown = rows.filter((r) => r.document === d && r.show).length;
        if (i) $nav.append(`<div class="ss-down">&#8595;</div>`);
        const $it = $(`<div class="ss-nav-item ${d === cur ? "active" : ""}"><span>${ss_esc(ss_nice(d))}</span><span class="ss-count">${shown}</span></div>`);
        $it.on("click", () => { frm.__ss_doc = d; ss_render_create(frm); });
        $nav.append($it);
    });
    const $more = $(`<div class="ss-nav-add">+ ${__("Another document")}</div>`);
    $more.on("click", () => {
        frappe.prompt({ fieldname: "dt", fieldtype: "Link", options: "DocType", label: __("Document"), reqd: 1,
            get_query: () => ({ filters: { istable: 0, issingle: 0 } }) },
        (v) => {
            frm.__ss_extra_docs = (frm.__ss_extra_docs || []).concat([v.dt]);
            frm.__ss_doc = v.dt;
            ss_render_create(frm);
        }, __("Add buttons to another document"), __("Continue"));
    });
    $nav.append($more);

    const $p = $w.find(".ss-panel");
    if (cur) {
        $p.append(`<div class="ss-h">${__("From a {0}, people can create:", [ss_esc(ss_nice(cur))])}</div>
            <div class="ss-hsub">${__("These appear in the <b>Create</b> menu at the top of the {0} form.", [ss_esc(ss_nice(cur))])}</div>`);
        rows.filter((r) => r.document === cur).forEach((r) => {
            const what = r.creates && r.creates !== r.button ? __("Makes a new {0}", [ss_esc(ss_nice(r.creates))]) + " &middot; " : "";
            const $c = $(`<div class="ss-card ${r.show ? "" : "off"}">
                ${ss_switch(r.show)}
                <div class="ss-text">
                    <div class="ss-title">${ss_esc(r.button)}${r.source === "New" ? `<span class="ss-tag">${__("added by you")}</span>` : ""}</div>
                    <div class="ss-sub">${what}${ss_esc(r.notes || "")}</div>
                </div>
                ${r.source === "New" ? `<span class="ss-del" title="${__("Remove")}">&#10005;</span>` : ""}
            </div>`);
            $c.find("input").on("change", function () {
                frappe.model.set_value(r.doctype, r.name, "show", this.checked ? 1 : 0);
                ss_render_create(frm);
            });
            $c.find(".ss-del").on("click", () => {
                frappe.confirm(__("Remove the {0} button?", [ss_esc(r.button)]), () => { ss_remove_row(frm, "create_buttons", r.name); ss_render_create(frm); });
            });
            $p.append($c);
        });
        const $add = $(`<div class="ss-add">+ ${__("Add a button to {0}", [ss_esc(ss_nice(cur))])}</div>`);
        $add.on("click", () => ss_add_dialog(frm, cur));
        $p.append($add);
    }
    f.$wrapper.empty().append($w);
    ss_adv_link(frm, "create_buttons", f.$wrapper);
}

function ss_add_dialog(frm, docname) {
    frappe.model.with_doctype(docname, () => {
        const skip = ["Section Break", "Column Break", "Tab Break", "HTML", "Table", "Table MultiSelect", "Button", "Attach", "Attach Image", "Text Editor", "Code"];
        const fields = (frappe.get_meta(docname).fields || []).filter((df) => df.label && !skip.includes(df.fieldtype));
        const opts = fields.map((df) => ({ label: df.label, value: df.fieldname }));
        const d = new frappe.ui.Dialog({
            title: __("Add a button to {0}", [ss_nice(docname)]),
            fields: [
                { fieldname: "creates", fieldtype: "Link", options: "DocType", reqd: 1, label: __("What should the button create?"),
                  get_query: () => ({ filters: { istable: 0, issingle: 0 } }) },
                { fieldname: "button", fieldtype: "Data", label: __("Button text"), description: __("Leave empty to use the name above") },
                { fieldname: "show_when", fieldtype: "Select", label: __("When should it appear?"), default: "Always",
                  options: [
                      { label: __("Always"), value: "Always" },
                      { label: __("Only after the {0} is submitted", [ss_nice(docname)]), value: "After Submit" },
                      { label: __("Only when a field has a certain value"), value: "Field has value" },
                  ] },
                { fieldname: "when_field", fieldtype: "Select", label: __("Which field?"), options: opts,
                  depends_on: "eval:doc.show_when=='Field has value'" },
                { fieldname: "when_value", fieldtype: "Data", label: __("Which value?"), description: __("For example: Completed"),
                  depends_on: "eval:doc.show_when=='Field has value'" },
            ],
            primary_action_label: __("Add Button"),
            primary_action(v) {
                if (v.show_when === "Field has value" && (!v.when_field || !v.when_value)) {
                    frappe.msgprint(__("Choose the field and type the value."));
                    return;
                }
                const lbl = (fields.find((x) => x.fieldname === v.when_field) || {}).label || v.when_field;
                const r = frm.add_child("create_buttons");
                Object.assign(r, {
                    show: 1, document: docname, button: v.button || ss_nice(v.creates), creates: v.creates,
                    source: "New", menu: "Create", show_when: v.show_when,
                    when_field: v.show_when === "Field has value" ? v.when_field : "",
                    when_value: v.show_when === "Field has value" ? v.when_value : "",
                    notes: ss_new_notes({ show_when: v.show_when, when_label: lbl, when_value: v.when_value }, docname),
                });
                frm.refresh_field("create_buttons");
                frm.dirty();
                d.hide();
                ss_render_create(frm);
                frappe.show_alert({ message: __("Button added. Click Save to apply it."), indicator: "green" });
            },
        });
        d.show();
    });
}

/* ---------------- Features ---------------- */
function ss_render_features(frm) {
    const f = frm.fields_dict.features_ui;
    if (!f) return;
    const $w = $(`<div><div class="ss-intro">${__("Switch extra features on or off for this site, then click <b>Save</b>.")}</div><div class="ss-list" style="max-width:820px"></div></div>`);
    const $l = $w.find(".ss-list");
    (frm.doc.features || []).forEach((r) => {
        const $c = $(`<div class="ss-card ${r.enabled ? "" : "off"}">
            ${ss_switch(r.enabled)}
            <div class="ss-text"><div class="ss-title">${ss_esc(r.feature)}</div><div class="ss-sub">${ss_esc(r.description || "")}</div></div>
        </div>`);
        $c.find("input").on("change", function () {
            frappe.model.set_value(r.doctype, r.name, "enabled", this.checked ? 1 : 0);
            ss_render_features(frm);
        });
        $l.append($c);
    });
    f.$wrapper.empty().append($w);
    ss_adv_link(frm, "features", f.$wrapper);
}

/* ---------------- Approval steps (workflows) ---------------- */
function ss_render_workflows(frm) {
    const f = frm.fields_dict.workflows_ui;
    if (!f) return;
    const rows = frm.doc.workflows || [];
    frm.__ss_wf = frm.__ss_wf || {};
    const missing = rows.filter((r) => r.workflow && !frm.__ss_wf[r.workflow]);
    if (missing.length && !frm.__ss_wf_loading) {
        frm.__ss_wf_loading = true;
        Promise.all(missing.map((r) => frappe.db.get_doc("Workflow", r.workflow).then((w) => { frm.__ss_wf[r.workflow] = w; }).catch(() => { frm.__ss_wf[r.workflow] = { states: [], transitions: [] }; })))
            .then(() => { frm.__ss_wf_loading = false; ss_render_workflows(frm); });
    }
    const $w = $(`<div><div class="ss-intro">${__("Each document moves through these steps using the <b>Actions</b> button. Switch a document's steps off if this business does not need them, or click <b>Edit steps</b> to rename steps or change who can approve.")}</div><div class="ss-list" style="max-width:900px"></div></div>`);
    const $l = $w.find(".ss-list");
    rows.forEach((r) => {
        const wf = frm.__ss_wf[r.workflow];
        let steps = `<span class="ss-sub">${__("Loading...")}</span>`;
        let who = "";
        if (wf) {
            steps = (wf.states || []).map((s) => `<span class="ss-step">${ss_esc(s.state)}</span>`).join(`<span class="ss-arrow">&rarr;</span>`);
            const roles = [...new Set((wf.transitions || []).map((t) => t.allowed).filter(Boolean))];
            if (roles.length) who = __("Who can move it forward: {0}", [roles.map(ss_esc).join(", ")]);
        }
        const $c = $(`<div class="ss-card ${r.is_active ? "" : "off"}">
            ${ss_switch(r.is_active)}
            <div class="ss-text">
                <div class="ss-title">${ss_esc(ss_nice(r.document_type || r.workflow))}</div>
                <div class="ss-steps">${steps}</div>
                <div class="ss-sub" style="margin-top:4px">${who}</div>
            </div>
            <span class="ss-btn">${__("Edit steps")}</span>
        </div>`);
        $c.find("input").on("change", function () {
            frappe.model.set_value(r.doctype, r.name, "is_active", this.checked ? 1 : 0);
            ss_render_workflows(frm);
        });
        $c.find(".ss-btn").on("click", () => {
            if (frm.is_dirty()) { frappe.msgprint(__("Please Save first.")); return; }
            frappe.set_route("Form", "Workflow", r.workflow);
        });
        $l.append($c);
    });
    f.$wrapper.empty().append($w);
    ss_adv_link(frm, "workflows", f.$wrapper);
}

function ss_render_all(frm) {
    ss_render_create(frm);
    ss_render_features(frm);
    ss_render_workflows(frm);
}

frappe.ui.form.on("Solar Settings", {
    onload(frm) {
        ["create_buttons", "features", "workflows"].forEach((t) => frm.set_df_property(t, "hidden", 1));
    },

    refresh(frm) {
        ss_css();
        ss_render_all(frm);

        frm.add_custom_button(__("Load Current Sidebar"), () => {
            const go = () => {
                frappe.db.get_doc("Workspace Sidebar", frm.doc.target_sidebar || "Solar").then((sb) => {
                    frm.clear_table("sidebar_items");
                    (sb.items || []).forEach((it) => {
                        const r = frm.add_child("sidebar_items");
                        r.enabled = 1;
                        r.type = it.type === "Section Break" ? "Section Break" : "Link";
                        r.label = it.label;
                        r.link_type = it.link_type || "DocType";
                        r.link_to = r.type === "Section Break" ? "" : it.link_to;
                        r.icon = it.icon;
                        r.child = it.child;
                        r.url = it.url;
                    });
                    frm.refresh_field("sidebar_items");
                    frm.dirty();
                    frappe.show_alert({ message: __("Loaded {0} items. Change them, then Save.", [(sb.items || []).length]), indicator: "green" });
                });
            };
            if ((frm.doc.sidebar_items || []).length) {
                frappe.confirm(__("Replace the sidebar rows with what the sidebar shows right now? Hidden rows will be lost."), go);
            } else { go(); }
        }, __("Load"));

        frm.add_custom_button(__("Load Solar Workflows"), () => {
            frappe.db.get_list("Workflow", { fields: ["name", "document_type", "is_active"], limit: 100, order_by: "name asc" }).then((rows) => {
                const have = (frm.doc.workflows || []).map((r) => r.workflow);
                let n = 0;
                rows.forEach((w) => {
                    if (have.includes(w.name)) return;
                    const r = frm.add_child("workflows");
                    r.workflow = w.name;
                    r.document_type = w.document_type;
                    r.is_active = w.is_active;
                    n++;
                });
                frm.refresh_field("workflows");
                if (n) frm.dirty();
                ss_render_workflows(frm);
                frappe.show_alert({ message: __("{0} workflow(s) added", [n]), indicator: "green" });
            });
        }, __("Load"));
    },

    target_sidebar(frm) {
        if (frm.doc.target_sidebar && (frm.doc.sidebar_items || []).length) {
            frappe.msgprint(__("Click Load > Load Current Sidebar to bring in the rows of {0}. Saving now would write the current rows into {0}.", [frm.doc.target_sidebar]));
        }
    },

    create_buttons_remove(frm) { ss_render_create(frm); },
    features_remove(frm) { ss_render_features(frm); },
    workflows_remove(frm) { ss_render_workflows(frm); },

    after_save(frm) {
        frm.__ss_wf = {};
        frappe.confirm(__("Saved and applied. Reload the page now so open forms and the sidebar pick up the changes?"), () => window.location.reload());
    },
});

