function sx_switch(on, disabled) {
    return `<label class="ss-sw" ${disabled ? 'style="opacity:.35;pointer-events:none"' : ""}><input type="checkbox" ${on ? "checked" : ""}><span></span></label>`;
}

function sx_adv(frm, tables, $w, rerender) {
    const hidden = frm.fields_dict[tables[0]].df.hidden;
    const $a = $(`<div class="ss-adv">${hidden ? __("Show advanced table") : __("Hide advanced table")}</div>`);
    $a.on("click", () => {
        tables.forEach((t) => frm.set_df_property(t, "hidden", hidden ? 0 : 1));
        rerender(frm);
    });
    $w.append($a);
}

function sx_drop(frm, table, name) {
    frm.doc[table] = (frm.doc[table] || []).filter((x) => x.name !== name);
    frm.doc[table].forEach((x, i) => (x.idx = i + 1));
    frm.refresh_field(table);
    frm.dirty();
}

/* ---------------- Forms ---------------- */
function sx_render_forms(frm) {
    const f = frm.fields_dict.custom_forms_ui;
    if (!f) return;
    const rules = frm.doc.custom_field_rules || [];
    const prints = frm.doc.custom_print_defaults || [];
    let docs = SX_DOCS.slice();
    rules.concat(prints).forEach((r) => { if (r.document && !docs.includes(r.document)) docs.push(r.document); });
    (frm.__sx_extra || []).forEach((d) => { if (!docs.includes(d)) docs.push(d); });
    if (!frm.__sx_form || !docs.includes(frm.__sx_form)) frm.__sx_form = docs[0];
    const cur = frm.__sx_form;

    const $w = $(`<div>
        <div class="sx-intro">${__("Pick a form on the left. Switch fields on or off, make them required, or give them a different name for this site. Changed fields are highlighted. Click <b>Save</b> when you are done; switching a change back puts the original back.")}</div>
        <div class="ss-wrap"><div class="ss-nav"></div><div class="ss-panel"></div></div>
    </div>`);
    const $nav = $w.find(".ss-nav");
    docs.forEach((d) => {
        const n = rules.filter((r) => r.document === d).length + prints.filter((r) => r.document === d).length;
        const $it = $(`<div class="ss-nav-item ${d === cur ? "active" : ""}"><span>${sx_esc(sx_nice(d))}</span>${n ? `<span class="ss-count">${n}</span>` : ""}</div>`);
        $it.on("click", () => { frm.__sx_form = d; frm.__sx_q = ""; sx_render_forms(frm); });
        $nav.append($it);
    });
    const $more = $(`<div class="ss-nav-add">+ ${__("Another form")}</div>`);
    $more.on("click", () => {
        frappe.prompt({ fieldname: "dt", fieldtype: "Link", options: "DocType", label: __("Form"), reqd: 1,
            get_query: () => ({ filters: { istable: 0, issingle: 0 } }) },
        (v) => { frm.__sx_extra = (frm.__sx_extra || []).concat([v.dt]); frm.__sx_form = v.dt; sx_render_forms(frm); },
        __("Change another form"), __("Continue"));
    });
    $nav.append($more);

    const $p = $w.find(".ss-panel");
    f.$wrapper.empty().append($w);
    sx_adv(frm, ["custom_print_defaults", "custom_field_rules"], f.$wrapper, sx_render_forms);

    frappe.model.with_doctype(cur, () => {
        const meta = frappe.get_meta(cur);

        // default print format
        const prow = prints.find((r) => r.document === cur);
        let std = meta.default_print_format || "";
        try {
            const st = JSON.parse(frm.doc.custom_applied_state || "{}").ps || {};
            const e = st[cur + "-main-default_print_format"];
            if (e) std = e.orig || "";
        } catch (e) { /* no saved state yet */ }
        const $pc = $(`<div class="sx-card"><div class="sx-ct">${__("Default print format")}</div>
            <div class="sx-cs">${__("The print format a {0} opens with. Leave empty to keep the standard one ({1}).", [sx_esc(sx_nice(cur)), sx_esc(std || __("Standard"))])}</div>
            <div class="sx-pf" style="max-width:360px"></div></div>`);
        $p.append($pc);
        const ctl = frappe.ui.form.make_control({
            parent: $pc.find(".sx-pf"),
            df: {
                fieldtype: "Link", options: "Print Format", fieldname: "sx_pf", placeholder: __("Standard"),
                get_query: () => ({ filters: { doc_type: cur, disabled: 0 } }),
                change() {
                    if (frm.__sx_pf_lock) return;
                    const v = ctl.get_value();
                    const row = (frm.doc.custom_print_defaults || []).find((r) => r.document === cur);
                    if (v && row && row.print_format === v) return;
                    if (!v && !row) return;
                    if (v) {
                        if (row) frappe.model.set_value(row.doctype, row.name, "print_format", v);
                        else { const r = frm.add_child("custom_print_defaults"); r.document = cur; r.print_format = v; frm.refresh_field("custom_print_defaults"); frm.dirty(); }
                    } else {
                        sx_drop(frm, "custom_print_defaults", row.name);
                    }
                },
            },
            render_input: true,
        });
        frm.__sx_pf_lock = true;
        ctl.set_value(prow ? prow.print_format : "").then(() => { frm.__sx_pf_lock = false; });

        // fields
        $p.append(`<div class="sx-ct" style="font-weight:600;font-size:14px;margin:6px 0 8px">${__("Fields on the {0} form", [sx_esc(sx_nice(cur))])}</div>`);
        const $q = $(`<input class="form-control sx-search" placeholder="${__("Find a field...")}">`).val(frm.__sx_q || "");
        $p.append($q);
        const $list = $(`<div class="sx-fields"><div class="sx-frow sx-head"><div>${__("Field")}</div><div>${__("Show")}</div><div>${__("Required")}</div><div class="sx-rcol">${__("Show as (new name)")}</div></div></div>`);
        $p.append($list);

        (meta.fields || []).forEach((df) => {
            if (!df.label || df.fieldtype === "Column Break") return;
            const row = rules.find((r) => r.document === cur && r.fieldname === df.fieldname);
            const orig_hidden = row ? row.orig_hidden : df.hidden;
            const orig_reqd = row ? row.orig_reqd : df.reqd;
            const show = row ? row.show : (df.hidden ? 0 : 1);
            const reqd = row ? row.required : (df.reqd ? 1 : 0);
            const label = row ? (row.field_label || df.label) : df.label;
            const is_sec = ["Section Break", "Tab Break"].includes(df.fieldtype);
            const $r = $(`<div class="sx-frow ${is_sec ? "sx-sec" : ""} ${row ? "changed" : ""}" data-q="${sx_esc((label + " " + df.fieldname).toLowerCase())}">
                <div class="sx-flabel" title="${sx_esc(df.fieldname)}">${sx_esc(label)}<span class="sx-fmeta">${sx_esc(is_sec ? df.fieldtype.replace(" Break", "") : df.fieldtype)}</span></div>
                <div class="sx-show">${sx_switch(show)}</div>
                <div class="sx-req">${sx_switch(reqd, SX_NO_REQD.includes(df.fieldtype))}</div>
                <div class="sx-rcol"><input class="form-control sx-rename" placeholder="${sx_esc(label)}" value="${sx_esc(row ? row.new_label || "" : "")}"></div>
            </div>`);
            const update = () => {
                const want_show = $r.find(".sx-show input").prop("checked") ? 1 : 0;
                const want_req = $r.find(".sx-req input").prop("checked") ? 1 : 0;
                const want_label = ($r.find(".sx-rename").val() || "").trim();
                let rw = (frm.doc.custom_field_rules || []).find((r) => r.document === cur && r.fieldname === df.fieldname);
                const same = want_show === (orig_hidden ? 0 : 1) && want_req === (orig_reqd ? 1 : 0) && !want_label;
                if (same) {
                    if (rw) sx_drop(frm, "custom_field_rules", rw.name);
                    $r.removeClass("changed");
                    return;
                }
                if (!rw) {
                    rw = frm.add_child("custom_field_rules");
                    Object.assign(rw, { document: cur, fieldname: df.fieldname, field_label: label, orig_hidden: orig_hidden ? 1 : 0, orig_reqd: orig_reqd ? 1 : 0 });
                }
                Object.assign(rw, { show: want_show, required: want_req, new_label: want_label });
                frm.refresh_field("custom_field_rules");
                frm.dirty();
                $r.addClass("changed");
            };
            $r.find("input[type=checkbox]").on("change", update);
            $r.find(".sx-rename").on("change", update);
            $list.append($r);
        });
        const filter = () => {
            const q = ($q.val() || "").trim().toLowerCase();
            frm.__sx_q = q;
            $list.find(".sx-frow:not(.sx-head)").each(function () { $(this).toggle(!q || $(this).attr("data-q").includes(q)); });
        };
        $q.on("input", filter);
        filter();
    });
}

/* ---------------- Work Stages ---------------- */
function sx_render_stages(frm) {
    const f = frm.fields_dict.custom_stages_ui;
    if (!f) return;
    const rows = frm.doc.custom_work_stages || [];
    const $w = $(`<div><div class="sx-intro">${__("These are the stage cards on the <b>Customer Work Stage</b> panel of every Customer, in this order. Rename them, change the icon, hide the ones this business does not use, or add a stage of your own (for example MNRE). Click <b>Save</b> when you are done.")}</div></div>`);

    if (!rows.length) {
        const $start = $(`<div class="sx-card"><div class="sx-ct">${__("Using the standard stages")}</div>
            <div class="sx-cs">${__("This site shows the standard 11 stages. Start from them to change the order or names.")}</div>
            <button class="btn btn-sm btn-default">${__("Start from the standard stages")}</button></div>`);
        $start.find("button").on("click", () => {
            SX_STAGES.forEach((s) => { const r = frm.add_child("custom_work_stages"); Object.assign(r, s, { show: 1, customer_field: "customer" }); });
            frm.refresh_field("custom_work_stages");
            frm.dirty();
            sx_render_stages(frm);
        });
        $w.append($start);
    } else {
        rows.forEach((r, i) => {
            const custom = !SX_BUILTIN_KEYS.includes(r.key);
            const done = r.done_values ? __("done when {0}", [sx_esc(r.done_values)]) : "";
            const $c = $(`<div class="sx-stage ${r.show ? "" : "off"}">
                <div class="sx-mv"><span class="sx-up" title="${__("Move up")}">&#9650;</span><span class="sx-dn" title="${__("Move down")}">&#9660;</span></div>
                <div class="sx-no">${i + 1}</div>
                ${sx_switch(r.show)}
                <input class="form-control sx-icon" value="${sx_esc(r.icon || "")}" title="${__("Icon")}">
                <input class="form-control sx-title" value="${sx_esc(r.title || "")}">
                <div class="sx-sdoc">${sx_esc(sx_nice(r.document))}${done ? " &middot; " + done : ""}${custom ? `<span class="ss-tag">${__("added by you")}</span>` : ""}</div>
                <label class="sx-opt"><input type="checkbox" class="sx-optional" ${r.optional ? "checked" : ""}> ${__("Optional")}</label>
                ${custom ? `<span class="ss-del" title="${__("Remove")}">&#10005;</span>` : ""}
            </div>`);
            const move = (d) => {
                const list = frm.doc.custom_work_stages;
                const j = i + d;
                if (j < 0 || j >= list.length) return;
                const tmp = list[i]; list[i] = list[j]; list[j] = tmp;
                list.forEach((x, k) => (x.idx = k + 1));
                frm.refresh_field("custom_work_stages");
                frm.dirty();
                sx_render_stages(frm);
            };
            $c.find(".sx-up").on("click", () => move(-1));
            $c.find(".sx-dn").on("click", () => move(1));
            $c.find(".ss-sw input").on("change", function () { frappe.model.set_value(r.doctype, r.name, "show", this.checked ? 1 : 0); sx_render_stages(frm); });
            $c.find(".sx-optional").on("change", function () { frappe.model.set_value(r.doctype, r.name, "optional", this.checked ? 1 : 0); });
            $c.find(".sx-title").on("change", function () { frappe.model.set_value(r.doctype, r.name, "title", this.value.trim() || r.title); });
            $c.find(".sx-icon").on("change", function () { frappe.model.set_value(r.doctype, r.name, "icon", this.value.trim()); });
            $c.find(".ss-del").on("click", () => frappe.confirm(__("Remove the {0} stage?", [sx_esc(r.title)]), () => { sx_drop(frm, "custom_work_stages", r.name); sx_render_stages(frm); }));
            $w.append($c);
        });
        const $add = $(`<div class="ss-add" style="max-width:860px">+ ${__("Add a stage")}</div>`);
        $add.on("click", () => sx_add_stage(frm));
        $w.append($add);
        const $reset = $(`<div class="ss-adv" style="margin-left:16px">${__("Back to the standard stages")}</div>`);
        $reset.on("click", () => frappe.confirm(__("Remove all your changes to the stages and use the standard 11 again?"), () => {
            frm.clear_table("custom_work_stages"); frm.refresh_field("custom_work_stages"); frm.dirty(); sx_render_stages(frm);
        }));
        $w.append($reset);
    }
    f.$wrapper.empty().append($w);
    sx_adv(frm, ["custom_work_stages"], f.$wrapper, sx_render_stages);
}

function sx_add_stage(frm) {
    const d = new frappe.ui.Dialog({
        title: __("Add a stage"),
        fields: [
            { fieldname: "document", fieldtype: "Link", options: "DocType", reqd: 1, label: __("Which document is this stage?"),
              description: __("It must have a Customer field, so the panel can find the customer's record."),
              get_query: () => ({ filters: { istable: 0, issingle: 0 } }),
              change() { sx_stage_fields(d); } },
            { fieldname: "title", fieldtype: "Data", label: __("Stage name"), description: __("Leave empty to use the document name") },
            { fieldname: "customer_field", fieldtype: "Select", label: __("Which field holds the Customer?") },
            { fieldname: "status_field", fieldtype: "Select", label: __("Which field shows its progress?"), description: __("Optional") },
            { fieldname: "done_values", fieldtype: "Data", label: __("The stage is done when that field is"), description: __("For example: Completed. Several: Completed, Approved") },
            { fieldname: "icon", fieldtype: "Data", label: __("Icon"), default: "📌", description: __("An emoji") },
            { fieldname: "optional", fieldtype: "Check", label: __("Optional stage (not every customer needs it)") },
        ],
        primary_action_label: __("Add Stage"),
        primary_action(v) {
            if (!v.customer_field) { frappe.msgprint(__("{0} has no field linked to Customer, so it cannot be shown as a customer stage.", [v.document])); return; }
            const r = frm.add_child("custom_work_stages");
            Object.assign(r, { show: 1, title: v.title || sx_nice(v.document), document: v.document, icon: v.icon || "", optional: v.optional ? 1 : 0,
                customer_field: v.customer_field, status_field: v.status_field || "", done_values: v.done_values || "" });
            frm.refresh_field("custom_work_stages");
            frm.dirty();
            d.hide();
            sx_render_stages(frm);
            frappe.show_alert({ message: __("Stage added. Click Save to apply it."), indicator: "green" });
        },
    });
    d.show();
}

function sx_stage_fields(d) {
    const dt = d.get_value("document");
    if (!dt) return;
    frappe.model.with_doctype(dt, () => {
        const fields = frappe.get_meta(dt).fields || [];
        const cust = fields.filter((df) => df.fieldtype === "Link" && df.options === "Customer")
            .map((df) => ({ label: df.label + " (" + df.fieldname + ")", value: df.fieldname }));
        const status = [{ label: "", value: "" }].concat(fields.filter((df) => ["Select", "Data"].includes(df.fieldtype) && df.label)
            .map((df) => ({ label: df.label + " (" + df.fieldname + ")", value: df.fieldname })));
        d.set_df_property("customer_field", "options", cust);
        d.set_df_property("status_field", "options", status);
        if (cust.length) d.set_value("customer_field", (cust.find((c) => c.value === "customer") || cust[0]).value);
        const st = status.find((s) => ["status", "workflow_state"].includes(s.value));
        if (st) d.set_value("status_field", st.value);
        if (!d.get_value("title")) d.set_value("title", sx_nice(dt));
    });
}

